R["cint-checkpoint-m1-task"] = "\nint build_verdict(const char *s) {\n    if (!s || !*s) return -1;\n    int idx = 0;\n    const char *p = s;\n    while (*p) {\n        if (*p == ' ') { p++; continue; }\n        if (*p == 'C') { idx++; p++; continue; }\n        if (*p == 'c') return -1 - idx;\n        if (*p == 'L') return idx;\n        if (*p == 'l') return -100;\n        p++;\n    }\n    return idx;\n}";
W["cint-checkpoint-m1-task"] = "\nint build_verdict(const char *s) {\n    if (!s || !*s) return -1;\n    int idx = 0;\n    for (const char *p = s; *p; p++) {\n        if (*p == ' ') continue;\n        if (*p == 'C') idx++;\n        if (*p == 'c') return -1;      /* wrong: loses the index */\n        if (*p == 'L') return idx;\n        if (*p == 'l') return -1;      /* wrong: not -100 */\n    }\n    return idx;\n}";
R["cint-p2-walk-sum"] = "\nlong long sum_walk(const int *a, size_t n) {\n    if (!a || n == 0) return 0;\n    long long t = 0;\n    for (const int *p = a, *e = a + n; p != e; ++p) t += *p;\n    return t;\n}\nlong long sum_reverse(const int *a, size_t n) {\n    if (!a || n == 0) return 0;\n    long long t = 0;\n    for (const int *p = a + n; p != a; --p) t += *(p - 1);\n    return t;\n}";
W["cint-p2-walk-sum"] = "\nlong long sum_walk(const int *a, size_t n) {\n    if (!a || n == 0) return 0;\n    long long t = 0;\n    for (size_t i = 0; i <= n; i++) t += a[i];   /* wrong: i <= n reads one past */\n    return t;\n}\nlong long sum_reverse(const int *a, size_t n) {\n    (void)a; (void)n;\n    return 0;   /* wrong: not implemented */\n}";
R["cint-p2-span"] = "\nsize_t span(const int *a, size_t n, const int *lo, const int *hi) {\n    if (!a || !lo || !hi || n == 0) return 0;\n    const int *first = a, *onepast = a + n;\n    if (lo < first || hi < first || lo > onepast || hi > onepast) return 0;\n    if (hi < lo) return 0;\n    return (size_t)(hi - lo);\n}";
