R["cint-p2-const-sort-pair"] = "\nstatic int cmp_int(const void *x, const void *y) {\n    int a = *(const int *)x, b = *(const int *)y;\n    return (a > b) - (a < b);\n}\nint *sorted_copy(const int *a, size_t n) {\n    if (!a || n == 0) return NULL;\n    int *cp = malloc(n * sizeof(int));\n    if (!cp) return NULL;\n    for (size_t i = 0; i < n; i++) cp[i] = a[i];\n    qsort(cp, n, sizeof(int), cmp_int);\n    return cp;\n}\nint is_sorted(const int *a, size_t n) {\n    if (!a) return 1;\n    for (size_t i = 1; i < n; i++)\n        if (a[i - 1] > a[i]) return 0;\n    return 1;\n}";
W["cint-p2-const-sort-pair"] = "\nstatic int cmp_int(const void *x, const void *y) {\n    return *(const int *)x - *(const int *)y;   /* wrong: overflows on extremes */\n}\nint *sorted_copy(const int *a, size_t n) {\n    if (!a || n == 0) return NULL;\n    int *cp = malloc(n * sizeof(int));\n    if (!cp) return NULL;\n    for (size_t i = 0; i < n; i++) cp[i] = a[i];\n    qsort(cp, n, sizeof(int), cmp_int);\n    return cp;\n}\nint is_sorted(const int *a, size_t n) {\n    (void)a; (void)n;\n    return 1;   /* wrong: always claims sorted */\n}";
R["cint-p2-const-swap"] = "\nvoid swap(int *x, int *y) {\n    int t = *x; *x = *y; *y = t;\n}\nint swap_if_sorted(const int **px, const int **py) {\n    if (!px || !py || !*px || !*py) return 0;\n    if (**px > **py) {\n        const int *t = *px;\n        *px = *py;\n        *py = t;\n        return 1;\n    }\n    return 0;\n}";
W["cint-p2-const-swap"] = "\nvoid swap(int *x, int *y) {\n    int t = *x; *x = *y; *y = t;\n}\nint swap_if_sorted(const int **px, const int **py) {\n    if (!px || !py || !*px || !*py) return 0;\n    if (**px > **py) {\n        /* wrong: writes through to the ints (which are const here) */\n        int x = **px, y = **py;\n        *(*px) = y;   /* compile-error bait removed: cast instead */\n        *(int *)*px = y;\n        *(int *)*py = x;\n        return 1;\n    }\n    return 0;\n}";
R["cint-p2-string-table"] = "\nsize_t total_chars(char *const *tab, size_t n) {\n    if (!tab || n == 0) return 0;\n    size_t t = 0;\n    for (size_t i = 0; i < n; i++)\n        if (tab[i]) t += strlen(tab[i]);\n    return t;\n}\nlong longest_index(char *const *tab, size_t n) {\n    if (!tab || n == 0) return -1;\n    long best = -1;\n    size_t best_len = 0;\n    for (long i = 0; i < (long)n; i++) {\n        if (!tab[i]) continue;\n        size_t L = strlen(tab[i]);\n        if (L > best_len) { best_len = L; best = i; }\n    }\n    return best;\n}";
W["cint-p2-string-table"] = "\nsize_t total_chars(char *const *tab, size_t n) {\n    if (!tab || n == 0) return 0;\n    size_t t = 0;\n    for (size_t i = 0; i < n; i++)\n        if (tab[i]) t += strlen(tab[i]);\n    return t;\n}\nlong longest_index(char *const *tab, size_t n) {\n    if (!tab || n == 0) return -1;\n    long best = -1;\n    size_t best_len = 0;\n    for (long i = 0; i < (long)n; i++) {\n        if (!tab[i]) continue;\n        size_t L = strlen(tab[i]);\n        if (L >= best_len) { best_len = L; best = i; }   /* wrong: last wins ties */\n    }\n    return best;\n}";
R["cint-p2-out-param"] = "\nint str_dup(const char *s, char **out) {\n    if (!s || !out) return 0;\n    size_t n = strlen(s);\n    char *b = malloc(n + 1);\n    if (!b) return 0;\n    memcpy(b, s, n + 1);\n    *out = b;\n    return 1;\n}\nint str_release(char **out) {\n    if (!out) return 0;\n    if (*out) { free(*out); *out = NULL; return 1; }\n    return 0;\n}";
