R["cint-checkpoint-m2-task"] = "\nint run_classify(const int *a, size_t n, const int *lo, const int *hi) {\n    if (!a || !lo || !hi || n == 0) return -1;\n    const int *first = a, *onepast = a + n;\n    if (lo < first || hi < first || lo > onepast || hi > onepast) return -1;\n    if (hi < lo) return -1;\n    size_t len = (size_t)(hi - lo);\n    if (len == 1) return 2;\n    for (const int *p = lo + 1; p < hi; p++)\n        if (*(p - 1) >= *p) return 1;\n    return 0;\n}";
W["cint-checkpoint-m2-task"] = "\nint run_classify(const int *a, size_t n, const int *lo, const int *hi) {\n    if (!a || !lo || !hi || n == 0) return -1;\n    const int *first = a, *onepast = a + n;\n    if (lo < first || hi < first || lo > onepast || hi > onepast) return -1;\n    if (hi < lo) return -1;\n    size_t len = (size_t)(hi - lo);\n    if (len == 1) return 2;\n    for (const int *p = lo + 1; p < hi; p++)\n        if (*(p - 1) > *p) return 1;   /* wrong: allows equal (not strict) */\n    return 0;\n}";
R["cint-p3-safe-dup"] = "\nint safe_dup(const char *s, char **out) {\n    if (!s || !out) return 0;\n    size_t n = strlen(s);\n    char *b = malloc(n + 1);\n    if (!b) return 0;\n    memcpy(b, s, n + 1);\n    *out = b;\n    return 1;\n}\nint path_join(const char *a, const char *b, char **out) {\n    if (!a || !b || !out) return 0;\n    size_t la = strlen(a), lb = strlen(b);\n    char *buf = malloc(la + lb + 2);\n    if (!buf) return 0;\n    memcpy(buf, a, la);\n    buf[la] = '/';\n    memcpy(buf + la + 1, b, lb + 1);\n    *out = buf;\n    return 1;\n}";
