R["cint-p5-opaque-counter"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\n#define MC_MAX 32\nstruct MCounter { char key[MC_MAX][16]; int count[MC_MAX]; size_t n; };\nMCounter *mc_create(void) {\n    return calloc(1, sizeof(MCounter));\n}\nint mc_bump(MCounter *m, const char *key, int by) {\n    if (!m || !key) return -1;\n    for (size_t i = 0; i < m->n; i++)\n        if (strcmp(m->key[i], key) == 0) { m->count[i] += by; return 0; }\n    if (m->n == MC_MAX || strlen(key) >= 16) return -1;\n    snprintf(m->key[m->n], 16, \"%s\", key);\n    m->count[m->n] = by;\n    m->n++;\n    return 0;\n}\nint mc_get(const MCounter *m, const char *key) {\n    if (!m || !key) return 0;\n    for (size_t i = 0; i < m->n; i++)\n        if (strcmp(m->key[i], key) == 0) return m->count[i];\n    return 0;\n}\nsize_t mc_keys(const MCounter *m) { return m ? m->n : 0; }\nvoid mc_destroy(MCounter *m) { free(m); }";
W["cint-p5-opaque-counter"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\n#define MC_MAX 32\nstruct MCounter { char key[MC_MAX][16]; int count[MC_MAX]; size_t n; };\nMCounter *mc_create(void) { return calloc(1, sizeof(MCounter)); }\nint mc_bump(MCounter *m, const char *key, int by) {\n    if (!m || !key) return -1;\n    for (size_t i = 0; i < m->n; i++)\n        if (strcmp(m->key[i], key) == 0) { m->count[i] = by; return 0; }  /* wrong: replaces instead of accumulating */\n    if (m->n == MC_MAX || strlen(key) >= 16) return -1;\n    snprintf(m->key[m->n], 16, \"%s\", key);\n    m->count[m->n] = by;\n    m->n++;\n    return 0;\n}\nint mc_get(const MCounter *m, const char *key) {\n    if (!m || !key) return 1;    /* wrong: returns 1 instead of 0 for missing/NULL */\n    for (size_t i = 0; i < m->n; i++)\n        if (strcmp(m->key[i], key) == 0) return m->count[i];\n    return 0;\n}\nsize_t mc_keys(const MCounter *m) { return m ? m->n + 1 : 0; }  /* wrong: off-by-one */\nvoid mc_destroy(MCounter *m) { if (m) m->n = 0; }  /* wrong: never frees */\n";
R["cint-p5-graph-free"] = "\n#include <stdlib.h>\n#include <stddef.h>\nstatic size_t sweep(GNode *n) {\n    if (!n || n->name == '\\0') return 0;   /* '\\0' marks freed */\n    n->name = '\\0';\n    size_t count = 1;\n    for (size_t i = 0; i < n->kids_len; i++) count += sweep(n->kids[i]);\n    free(n->kids);\n    free(n);\n    return count;\n}\nsize_t graph_free(GNode *root) { return sweep(root); }";
W["cint-p5-graph-free"] = "\n#include <stdlib.h>\n#include <stddef.h>\nsize_t graph_free(GNode *root) {\n    if (!root) return 0;\n    size_t count = 0;\n    for (size_t i = 0; i < root->kids_len; i++) {\n        count += graph_free(root->kids[i]);   /* wrong: shared nodes freed multiple times */\n    }\n    free(root->kids);\n    free(root);\n    return count + 1;\n}";
R["cint-checkpoint-m5-task"] = "\n#include <string.h>\n#include <stddef.h>\nstruct BQueue { char slot[8][32]; size_t head, count; };\nBQueue *bq_create(void) { return calloc(1, sizeof(BQueue)); }\nint bq_push(BQueue *q, const char *s) {\n    if (!q || !s || strlen(s) >= 32 || q->count == 8) return -1;\n    size_t tail = (q->head + q->count) % 8;\n    snprintf(q->slot[tail], 32, \"%s\", s);\n    q->count++;\n    return 0;\n}\nint bq_pop(BQueue *q, char *out) {\n    if (!q || !out || q->count == 0) return -1;\n    snprintf(out, 32, \"%s\", q->slot[q->head]);\n    q->head = (q->head + 1) % 8;\n    q->count--;\n    return 0;\n}\nsize_t bq_len(const BQueue *q) { return q ? q->count : 0; }\nsize_t bq_capacity(const BQueue *q) { (void)q; return 8; }\nvoid bq_destroy(BQueue *q) { free(q); }";
W["cint-checkpoint-m5-task"] = "\n#include <string.h>\n#include <stddef.h>\nstruct BQueue { char slot[8][32]; size_t head, count; };\nBQueue *bq_create(void) { return calloc(1, sizeof(BQueue)); }\nint bq_push(BQueue *q, const char *s) {\n    if (!q || !s || strlen(s) >= 32 || q->count == 8) return -1;\n    snprintf(q->slot[q->count], 32, \"%s\", s);   /* wrong: fills from 0, ignores head */\n    q->count++;\n    return 0;\n}\nint bq_pop(BQueue *q, char *out) {\n    if (!q || !out || q->count == 0) return -1;\n    snprintf(out, 32, \"%s\", q->slot[0]);        /* wrong: always slot 0, no ring advance */\n    for (size_t i = 1; i < q->count; i++)\n        snprintf(q->slot[i - 1], 32, \"%s\", q->slot[i]);  /* wrong: still wrong after full+wrap */\n    q->count--;\n    return 0;\n}\nsize_t bq_len(const BQueue *q) { return q ? q->count : 1; }  /* wrong: empty returns 1 */\nsize_t bq_capacity(const BQueue *q) { (void)q; return 8; }\nvoid bq_destroy(BQueue *q) { free(q); }";
R["cint-p6-bounded-copy"] = "\n#include <string.h>\n#include <stddef.h>\nint copy_bounded(char *dst, size_t dstcap, const char *src) {\n    if (!dst || dstcap == 0 || !src) return -1;\n    size_t slen = strlen(src);\n    if (slen + 1 <= dstcap) {\n        memmove(dst, src, slen + 1);          /* memmove: src==dst safe */\n        return 0;\n    }\n    if (dstcap > 1) {\n        memmove(dst, src, dstcap - 1);\n        dst[dstcap - 1] = '\\0';\n    } else {\n        dst[0] = '\\0';\n    }\n    return 1;\n}\nsize_t copy_needed(const char *src) { return src ? strlen(src) : 0; }";
W["cint-p6-bounded-copy"] = "\n#include <string.h>\n#include <stddef.h>\nint copy_bounded(char *dst, size_t dstcap, const char *src) {\n    if (!dst || !src) return -1;              /* wrong: dstcap==0 accepted */\n    size_t slen = strlen(src);\n    if (slen <= dstcap) {\n        memcpy(dst, src, slen + 1);           /* wrong: slen == dstcap overruns by the '\\0' */\n        return 0;\n    }\n    memcpy(dst, src, dstcap);                 /* wrong: no room for '\\0' */\n    return 1;\n}\nsize_t copy_needed(const char *src) { return src ? strlen(src) + 1 : 0; }  /* wrong: counts '\\0' */\n";
R["cint-p6-strbuf"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\nvoid sb_init(StrBuf *b) {\n    if (!b) return;\n    b->data = NULL;\n    b->len = 0;\n    b->cap = 0;\n}\nint sb_append(StrBuf *b, const char *s) {\n    if (!b || !s) return -1;\n    size_t slen = strlen(s);\n    size_t need = b->len + slen + 1;\n    if (need > b->cap) {\n        size_t ncap = b->cap ? b->cap : 16;\n        while (ncap < need) ncap *= 2;\n        char *nd = realloc(b->data, ncap);\n        if (!nd) return -1;\n        b->data = nd;\n        b->cap = ncap;\n    }\n    if (b->len == 0) b->data[0] = '\\0';\n    memcpy(b->data + b->len, s, slen + 1);\n    b->len += slen;\n    return 0;\n}\nvoid sb_free(StrBuf *b) {\n    if (!b) return;\n    free(b->data);\n    sb_init(b);\n}";
W["cint-p6-strbuf"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\nvoid sb_init(StrBuf *b) {\n    if (!b) return;\n    b->data = NULL; b->len = 0; b->cap = 0;\n}\nint sb_append(StrBuf *b, const char *s) {\n    if (!b || !s) return -1;\n    size_t slen = strlen(s);\n    size_t need = b->len + slen + 1;\n    if (need > b->cap) {\n        size_t ncap = b->cap ? b->cap : 16;\n        while (ncap < need) ncap *= 2;\n        b->data = realloc(b->data, ncap);     /* wrong: old block leaked on failure */\n        if (!b->data) return -1;\n        b->cap = ncap;\n    }\n    if (b->len == 0) b->data[0] = '\\0';\n    memcpy(b->data + b->len, s, slen);        /* wrong: '\\0' not copied */\n    b->len += slen;\n    return 0;\n}\nvoid sb_free(StrBuf *b) {\n    if (!b) return;\n    free(b->data);\n    b->data = NULL;                           /* wrong: len/cap left stale */\n}";
R["cint-p6-span-split"] = "\n#include <string.h>\n#include <stddef.h>\nint split_spans(const char *line, Span *spans, size_t cap) {\n    if (!line || !spans) return -1;\n    if (*line == '\\0') return 0;              /* empty line: no tokens */\n    size_t n = 0;\n    const char *p = line;\n    while (1) {\n        const char *start = p;\n        while (*p && *p != ',') p++;\n        if (n == cap) return -1;\n        spans[n].start = start;\n        spans[n].len = (size_t)(p - start);\n        n++;\n        if (*p == '\\0') break;\n        p++;                       /* skip the comma */\n        if (*p == '\\0') {          /* trailing comma: one empty token */\n            if (n == cap) return -1;\n            spans[n].start = p;\n            spans[n].len = 0;\n            n++;\n            break;\n        }\n    }\n    return (int)n;\n}";
W["cint-p6-span-split"] = "\n#include <string.h>\n#include <stddef.h>\nint split_spans(const char *line, Span *spans, size_t cap) {\n    if (!line || !spans) return -1;\n    size_t n = 0;\n    const char *p = line;\n    while (*p) {\n        const char *start = p;\n        while (*p && *p != ',') p++;\n        if (n == cap) return -1;\n        spans[n].start = start;\n        spans[n].len = (size_t)(p - start);\n        n++;\n        if (*p) p++;\n    }\n    return (int)n;                 /* wrong: trailing comma lost, \"\" -> 0 spans */\n}";
R["cint-p6-numbers"] = "\n#include <string.h>\n#include <stddef.h>\nint parse_range(const char *s, long min, long max, long *out) {\n    if (!s || !out || !*s) return -1;\n    int neg = 0;\n    const char *p = s;\n    if (*p == '-') { neg = 1; p++; if (!*p) return -1; }\n    long v = 0;\n    for (; *p; p++) {\n        if (*p < '0' || *p > '9') return -1;\n        v = v * 10 + (*p - '0');\n        if (v > 1000000000L) return -1;      /* cheap overflow guard */\n    }\n    if (neg) v = -v;\n    if (v < min || v > max) return -1;\n    *out = v;\n    return 0;\n}";
W["cint-p6-numbers"] = "\n#include <stdlib.h>\n#include <string.h>\n#include <stddef.h>\nint parse_range(const char *s, long min, long max, long *out) {\n    if (!s || !out || !*s) return -1;\n    char *end;\n    long v = strtol(s, &end, 10);   /* wrong: accepts \"  42\" and \"+42\" and \"42\\n\" */\n    if (*end != '\\0' && *end != '\\n') return -1;\n    if (v < min || v > max) return -1;\n    *out = v;\n    return 0;\n}";
R["cint-checkpoint-m6-task"] = "\n#include <string.h>\n#include <stddef.h>\nstatic int parse_num(const char *start, size_t len, long lo, long hi, int *out) {\n    if (len == 0) return -1;\n    long v = 0;\n    for (size_t i = 0; i < len; i++) {\n        if (start[i] < '0' || start[i] > '9') return -1;\n        v = v * 10 + (start[i] - '0');\n        if (v > 1000000L) return -1;\n    }\n    if (v < lo || v > hi) return -1;\n    *out = (int)v;\n    return 0;\n}\nint csv_parse(const char *line, char name[16], int *age, int *score) {\n    if (!line || !name || !age || !score) return -1;\n    const char *sp[3];\n    size_t sl[3];\n    int n = 0;\n    const char *p = line;\n    while (1) {\n        const char *start = p;\n        while (*p && *p != ',') p++;\n        if (n == 3) return -1;                 /* 4+ fields */\n        sp[n] = start;\n        sl[n] = (size_t)(p - start);\n        n++;\n        if (*p == '\\0') break;\n        p++;\n        if (*p == '\\0') return -1;             /* trailing comma */\n    }\n    if (n != 3) return -1;                     /* fewer fields */\n    if (sl[0] == 0 || sl[0] > 15) return -1;\n    if (memchr(sp[0], ',', sl[0])) return -1;  /* cannot happen post-split; belt and braces */\n    memcpy(name, sp[0], sl[0]);\n    name[sl[0]] = '\\0';\n    if (parse_num(sp[1], sl[1], 0, 130, age) != 0) return -1;\n    if (parse_num(sp[2], sl[2], 0, 100, score) != 0) return -1;\n    return 0;\n}";
W["cint-checkpoint-m6-task"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\nint csv_parse(const char *line, char name[16], int *age, int *score) {\n    if (!line || !name || !age || !score) return -1;\n    char buf[256];\n    snprintf(buf, sizeof buf, \"%s\", line);\n    char *save = buf;\n    char *f1 = strtok(save, \",\");\n    char *f2 = strtok(NULL, \",\");\n    char *f3 = strtok(NULL, \",\");\n    if (!f1 || !f2 || !f3) return -1;\n    if (!*f1 || strlen(f1) > 15) return -1;\n    strcpy(name, f1);\n    *age = atoi(f2);      /* wrong: accepts \"abc\" as 0, \"30.5\" as 30, \" 30\" */\n    *score = atoi(f3);    /* wrong: no range checks, no junk rejection */\n    return 0;             /* wrong: \"ann,30,95,extra\" wrongly accepted */\n}";
R["cint-p7-slist-core"] = "\n#include <stdlib.h>\n#include <stddef.h>\nint s_push(SNode **head, int v) {\n    if (!head) return -1;\n    SNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->value = v;\n    n->next = *head;\n    *head = n;\n    return 0;\n}\nint s_pop(SNode **head, int *out) {\n    if (!head || !*head || !out) return -1;\n    SNode *n = *head;\n    *out = n->value;\n    *head = n->next;\n    free(n);\n    return 0;\n}\nint s_remove(SNode **head, int v) {\n    if (!head) return 0;\n    SNode **link = head;\n    for (SNode *cur = *head; cur; cur = cur->next) {\n        if (cur->value == v) {\n            *link = cur->next;\n            free(cur);\n            return 1;\n        }\n        link = &cur->next;\n    }\n    return 0;\n}\nsize_t s_len(const SNode *head) {\n    size_t n = 0;\n    for (const SNode *p = head; p; p = p->next) n++;\n    return n;\n}\nint s_sum(const SNode *head) {\n    int t = 0;\n    for (const SNode *p = head; p; p = p->next) t += p->value;\n    return t;\n}\nvoid s_clear(SNode **head) {\n    if (!head) return;\n    SNode *cur = *head;\n    while (cur) {\n        SNode *next = cur->next;\n        free(cur);\n        cur = next;\n    }\n    *head = NULL;\n}\nint s_insert_sorted(SNode **head, int v) {\n    if (!head) return -1;\n    SNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->value = v;\n    SNode **link = head;\n    while (*link && (*link)->value <= v) link = &(*link)->next;\n    n->next = *link;\n    *link = n;\n    return 0;\n}";
W["cint-p7-slist-core"] = "\n#include <stdlib.h>\n#include <stddef.h>\nint s_push(SNode **head, int v) {\n    if (!head) return -1;\n    SNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->value = v;\n    n->next = *head;\n    *head = n;\n    return 0;\n}\nint s_pop(SNode **head, int *out) {\n    if (!head || !*head || !out) return -1;\n    SNode *n = *head;\n    *out = n->value;\n    free(n);                      /* wrong: *head now dangles */\n    *head = n->next;              /* wrong: use-after-free ordering */\n    return 0;\n}\nint s_remove(SNode **head, int v) {\n    if (!head) return 0;\n    for (SNode *cur = *head; cur; cur = cur->next) {\n        if (cur->value == v) {\n            free(cur);            /* wrong: previous node still points here */\n            return 1;\n        }\n        cur = cur->next;          /* wrong: also reads freed memory on the walk */\n    }\n    return 0;\n}\nsize_t s_len(const SNode *head) {\n    size_t n = 0;\n    for (const SNode *p = head; p; p = p->next) n++;\n    return n;\n}\nint s_sum(const SNode *head) {\n    int t = 0;\n    for (const SNode *p = head; p; p = p->next) t += p->value;\n    return t;\n}\nvoid s_clear(SNode **head) {\n    if (!head) return;\n    SNode *cur = *head;\n    while (cur) {\n        free(cur);                /* wrong: cur->next read after free */\n        cur = cur->next;\n    }\n    *head = NULL;\n}\nint s_insert_sorted(SNode **head, int v) {\n    if (!head) return -1;\n    SNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->value = v;\n    SNode **link = head;\n    while (*link && (*link)->value < v) link = &(*link)->next;   /* wrong: < puts equal values AFTER existing equals (unstable) \u2014 hidden by tiny tests, but wrong contract */\n    n->next = *link;\n    *link = n;\n    return 0;\n}";
R["cint-p7-slist-algos"] = "\n#include <stdlib.h>\n#include <stddef.h>\nvoid s_reverse(SNode **head) {\n    if (!head) return;\n    SNode *prev = NULL, *cur = *head;\n    while (cur) {\n        SNode *next = cur->next;\n        cur->next = prev;\n        prev = cur;\n        cur = next;\n    }\n    *head = prev;\n}\nint s_middle(const SNode *head) {\n    if (!head) return -1;\n    const SNode *slow = head, *fast = head;\n    while (fast->next && fast->next->next) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    return slow->value;\n}\nint s_is_sorted(const SNode *head) {\n    for (const SNode *p = head; p && p->next; p = p->next)\n        if (p->value > p->next->value) return 0;\n    return 1;\n}\nvoid s_remove_all(SNode **head, int v) {\n    if (!head) return;\n    SNode **link = head;\n    while (*link) {\n        if ((*link)->value == v) {\n            SNode *doomed = *link;\n            *link = doomed->next;\n            free(doomed);\n        } else {\n            link = &(*link)->next;\n        }\n    }\n}";
W["cint-p7-slist-algos"] = "\n#include <stdlib.h>\n#include <stddef.h>\nvoid s_reverse(SNode **head) {\n    if (!head || !*head) return;\n    SNode *prev = NULL, *cur = *head;\n    while (cur) {\n        SNode *next = cur->next;\n        cur->next = prev;\n        prev = cur;\n        cur = next;\n    }\n    *head = prev;\n}\nint s_middle(const SNode *head) {\n    if (!head) return -1;\n    const SNode *slow = head, *fast = head->next;   /* wrong: fast starts one ahead */\n    while (fast && fast->next) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    return slow->value;\n}\nint s_is_sorted(const SNode *head) {\n    if (!head) return 0;                 /* wrong: empty is sorted */\n    for (const SNode *p = head; p && p->next; p = p->next)\n        if (p->value > p->next->value) return 0;\n    return 1;\n}\nvoid s_remove_all(SNode **head, int v) {\n    if (!head) return;\n    for (SNode *cur = *head; cur; cur = cur->next) {\n        if (cur->value == v) {\n            SNode *doomed = cur;\n            free(doomed);                /* wrong: prev still points at freed node */\n            cur = cur->next;             /* wrong: read after free */\n        }\n    }\n}";
R["cint-p7-deque"] = "\n#include <stdlib.h>\n#include <stddef.h>\nvoid dq_init(DNode *s) {\n    if (!s) return;\n    s->prev = s;\n    s->next = s;\n}\nstatic void link_after(DNode *at, DNode *n) {\n    n->prev = at;\n    n->next = at->next;\n    at->next->prev = n;\n    at->next = n;\n}\nvoid dq_push_front(DNode *s, int v) {\n    if (!s) return;\n    DNode *n = malloc(sizeof *n);\n    if (!n) return;\n    n->value = v;\n    link_after(s, n);\n}\nvoid dq_push_back(DNode *s, int v) {\n    if (!s) return;\n    DNode *n = malloc(sizeof *n);\n    if (!n) return;\n    n->value = v;\n    link_after(s->prev, n);\n}\nstatic int unlink_pop(DNode *victim, int *out) {\n    *out = victim->value;\n    victim->prev->next = victim->next;\n    victim->next->prev = victim->prev;\n    free(victim);\n    return 0;\n}\nint dq_pop_front(DNode *s, int *out) {\n    if (!s || !out || s->next == s) return -1;\n    return unlink_pop(s->next, out);\n}\nint dq_pop_back(DNode *s, int *out) {\n    if (!s || !out || s->prev == s) return -1;\n    return unlink_pop(s->prev, out);\n}\nsize_t dq_len(const DNode *s) {\n    if (!s) return 0;\n    size_t n = 0;\n    for (const DNode *p = s->next; p != s; p = p->next) n++;\n    return n;\n}\nint dq_consistent(const DNode *s) {\n    if (!s) return 0;\n    /* forward walk: every node's links must be mutual, and the walk\n       must return home; backward walk must take exactly as many steps. */\n    size_t forward = 0;\n    for (const DNode *p = s->next; p != s; p = p->next) {\n        if (p->next->prev != p) return 0;   /* forward chain consistent */\n        if (p->prev->next != p) return 0;   /* backward chain consistent */\n        forward++;\n        if (forward > 1000000) return 0;    /* cycle guard */\n    }\n    size_t backward = 0;\n    for (const DNode *p = s->prev; p != s; p = p->prev) {\n        backward++;\n        if (backward > forward) return 0;\n    }\n    return forward == backward;\n}";
W["cint-p7-deque"] = "\n#include <stdlib.h>\n#include <stddef.h>\nvoid dq_init(DNode *s) {\n    if (!s) return;\n    s->prev = s;\n    s->next = s;\n}\nvoid dq_push_front(DNode *s, int v) {\n    if (!s) return;\n    DNode *n = malloc(sizeof *n);\n    if (!n) return;\n    n->value = v;\n    n->next = s->next;\n    s->next = n;              /* wrong: forgot n->prev and the back-link fix */\n    n->prev = s;\n}\nvoid dq_push_back(DNode *s, int v) {\n    if (!s) return;\n    DNode *n = malloc(sizeof *n);\n    if (!n) return;\n    n->value = v;\n    n->prev = s->prev;\n    s->prev = n;              /* wrong: forgot n->next and the forward-link fix */\n    n->next = s;\n}\nint dq_pop_front(DNode *s, int *out) {\n    if (!s || !out || s->next == s) return -1;\n    DNode *n = s->next;\n    *out = n->value;\n    s->next = n->next;        /* wrong: n->next's prev still points at freed node */\n    free(n);\n    return 0;\n}\nint dq_pop_back(DNode *s, int *out) {\n    if (!s || !out || s->prev == s) return -1;\n    DNode *n = s->prev;\n    *out = n->value;\n    s->prev = n->prev;        /* wrong: same, other direction */\n    free(n);\n    return 0;\n}\nsize_t dq_len(const DNode *s) {\n    if (!s) return 0;\n    size_t n = 0;\n    for (const DNode *p = s->next; p != s; p = p->next) n++;\n    return n;\n}\nint dq_consistent(const DNode *s) {\n    if (!s) return 0;\n    return 1;                 /* wrong: claims consistency without checking */\n}";
R["cint-checkpoint-m7-task"] = "\n#include <stdlib.h>\n#include <stddef.h>\nSNode *s_merge_sorted(SNode **a_head, SNode **b_head) {\n    if (!a_head || !b_head) return NULL;\n    SNode *a = *a_head, *b = *b_head;\n    SNode *head = NULL, **tail = &head;\n    while (a && b) {\n        SNode **take = (a->value <= b->value) ? &a : &b;\n        SNode *n = *take;\n        *take = n->next;          /* advance the list we took from */\n        n->next = NULL;\n        *tail = n;                /* append to output */\n        tail = &n->next;\n    }\n    SNode *rest = a ? a : b;      /* append the leftover run */\n    *tail = rest;\n    *a_head = NULL;\n    *b_head = NULL;\n    return head;\n}";
W["cint-checkpoint-m7-task"] = "\n#include <stdlib.h>\n#include <stddef.h>\nSNode *s_merge_sorted(SNode **a_head, SNode **b_head) {\n    if (!a_head || !b_head) return NULL;\n    SNode *a = *a_head, *b = *b_head;\n    SNode *head = NULL, **tail = &head;\n    while (a && b) {\n        if (a->value < b->value) {          /* wrong: < loses ties' stability AND\n                                               advances the wrong list below on equal */\n            SNode *n = a;\n            a = n->next;\n            n->next = NULL;\n            *tail = n;\n            tail = &n->next;\n        } else {\n            SNode *n = b;\n            b = n->next;\n            n->next = a->next;              /* wrong: corrupts a's chain */\n            *tail = n;\n            tail = &n->next;\n        }\n    }\n    *tail = a ? a : b;\n    *a_head = NULL;\n    *b_head = NULL;\n    return head;\n}";
R["cint-p8-linear"] = "\n#include <string.h>\n#include <stddef.h>\nvoid otab_init(OTab *t) {\n    if (!t) return;\n    memset(t, 0, sizeof *t);\n}\nstatic size_t bucket(long key) { return (size_t)key % OTAB_CAP; }\nint otab_put(OTab *t, long key, int value) {\n    if (!t) return -1;\n    size_t i = bucket(key);\n    size_t tomb = (size_t)-1;\n    for (size_t probe = 0; probe < OTAB_CAP; probe++) {\n        OSlot *s = &t->slots[i];\n        if (s->status == 1 && s->key == key) {\n            s->value = value;\n            return 1;                     /* updated */\n        }\n        if (s->status == 0) {\n            /* insert at first tombstone if seen, else here */\n            size_t at = (tomb != (size_t)-1) ? tomb : i;\n            t->slots[at].key = key;\n            t->slots[at].value = value;\n            t->slots[at].status = 1;\n            t->count++;\n            return 0;\n        }\n        if (s->status == 2 && tomb == (size_t)-1) tomb = i;\n        i = (i + 1) % OTAB_CAP;\n    }\n    if (tomb != (size_t)-1) {             /* full of tombstones/occupied: reuse tombstone */\n        t->slots[tomb].key = key;\n        t->slots[tomb].value = value;\n        t->slots[tomb].status = 1;\n        t->count++;\n        return 0;\n    }\n    return -1;                            /* truly full */\n}\nint otab_get(const OTab *t, long key, int *out) {\n    if (!t || !out) return -1;\n    size_t i = bucket(key);\n    for (size_t probe = 0; probe < OTAB_CAP; probe++) {\n        const OSlot *s = &t->slots[i];\n        if (s->status == 0) return -1;    /* empty terminates the probe */\n        if (s->status == 1 && s->key == key) {\n            *out = s->value;\n            return 0;\n        }\n        i = (i + 1) % OTAB_CAP;           /* tombstones and other keys: keep probing */\n    }\n    return -1;\n}\nint otab_del(OTab *t, long key) {\n    if (!t) return 0;\n    size_t i = bucket(key);\n    for (size_t probe = 0; probe < OTAB_CAP; probe++) {\n        OSlot *s = &t->slots[i];\n        if (s->status == 0) return 0;\n        if (s->status == 1 && s->key == key) {\n            s->status = 2;                /* tombstone */\n            t->count--;\n            return 1;\n        }\n        i = (i + 1) % OTAB_CAP;\n    }\n    return 0;\n}\nsize_t otab_size(const OTab *t) { return t ? t->count : 0; }";
W["cint-p8-linear"] = "\n#include <string.h>\n#include <stddef.h>\nvoid otab_init(OTab *t) {\n    if (!t) return;\n    memset(t, 0, sizeof *t);\n}\nstatic size_t bucket(long key) { return (size_t)key % OTAB_CAP; }\nint otab_put(OTab *t, long key, int value) {\n    if (!t) return -1;\n    size_t i = bucket(key);\n    for (size_t probe = 0; probe < OTAB_CAP; probe++) {\n        OSlot *s = &t->slots[i];\n        if (s->status == 1 && s->key == key) {\n            s->value = value;\n            return 1;\n        }\n        if (s->status != 1) {             /* wrong: inserts onto a TOMBSTONE\n                                             without checking whether the key\n                                             already lives further along the probe\n                                             chain -> duplicate keys */\n            s->key = key;\n            s->value = value;\n            s->status = 1;\n            t->count++;\n            return 0;\n        }\n        i = (i + 1) % OTAB_CAP;\n    }\n    return -1;\n}\nint otab_get(const OTab *t, long key, int *out) {\n    if (!t || !out) return -1;\n    size_t i = bucket(key);\n    for (size_t probe = 0; probe < OTAB_CAP; probe++) {\n        const OSlot *s = &t->slots[i];\n        if (s->status == 0 || s->status == 2) return -1;  /* wrong: tombstone\n                                             stops the probe -> entries after a\n                                             deletion become unreachable */\n        if (s->status == 1 && s->key == key) {\n            *out = s->value;\n            return 0;\n        }\n        i = (i + 1) % OTAB_CAP;\n    }\n    return -1;\n}\nint otab_del(OTab *t, long key) {\n    if (!t) return 0;\n    size_t i = bucket(key);\n    for (size_t probe = 0; probe < OTAB_CAP; probe++) {\n        OSlot *s = &t->slots[i];\n        if (s->status == 0) return 0;\n        if (s->status == 1 && s->key == key) {\n            memset(s, 0, sizeof *s);      /* wrong: empty hole cuts the probe chain */\n            t->count--;\n            return 1;\n        }\n        i = (i + 1) % OTAB_CAP;\n    }\n    return 0;\n}\nsize_t otab_size(const OTab *t) { return t ? t->count : 0; }";
R["cint-p8-hmap"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\nstatic size_t fnv1a(const char *s) {\n    size_t h = 2166136261u;\n    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {\n        h ^= *p;\n        h *= 16777619u;\n    }\n    return h;\n}\nvoid hmap_init(HMap *m) {\n    if (!m) return;\n    memset(m, 0, sizeof *m);\n}\nint hmap_put(HMap *m, const char *key, int value) {\n    if (!m || !key) return -1;\n    size_t b = fnv1a(key) % HMAP_BUCKETS;\n    for (HNode *n = m->buckets[b]; n; n = n->next)\n        if (strcmp(n->key, key) == 0) {\n            n->value = value;\n            return 1;\n        }\n    HNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->key = key;\n    n->value = value;\n    n->next = m->buckets[b];\n    m->buckets[b] = n;\n    m->count++;\n    return 0;\n}\nint hmap_get(const HMap *m, const char *key, int *out) {\n    if (!m || !key || !out) return -1;\n    size_t b = fnv1a(key) % HMAP_BUCKETS;\n    for (const HNode *n = m->buckets[b]; n; n = n->next)\n        if (strcmp(n->key, key) == 0) {\n            *out = n->value;\n            return 0;\n        }\n    return -1;\n}\nint hmap_del(HMap *m, const char *key) {\n    if (!m || !key) return 0;\n    size_t b = fnv1a(key) % HMAP_BUCKETS;\n    HNode **link = &m->buckets[b];\n    while (*link) {\n        HNode *n = *link;\n        if (strcmp(n->key, key) == 0) {\n            *link = n->next;\n            free(n);\n            m->count--;\n            return 1;\n        }\n        link = &n->next;\n    }\n    return 0;\n}\nsize_t hmap_size(const HMap *m) { return m ? m->count : 0; }\nsize_t hmap_max_chain(const HMap *m) {\n    if (!m) return 0;\n    size_t mx = 0;\n    for (size_t b = 0; b < HMAP_BUCKETS; b++) {\n        size_t len = 0;\n        for (const HNode *n = m->buckets[b]; n; n = n->next) len++;\n        if (len > mx) mx = len;\n    }\n    return mx;\n}\nvoid hmap_destroy(HMap *m) {\n    if (!m) return;\n    for (size_t b = 0; b < HMAP_BUCKETS; b++)\n        while (m->buckets[b]) {\n            HNode *n = m->buckets[b];\n            m->buckets[b] = n->next;\n            free(n);\n        }\n    m->count = 0;\n}";
W["cint-p8-hmap"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\nstatic size_t fnv1a(const char *s) {\n    size_t h = 2166136261u;\n    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {\n        h ^= *p;\n        h *= 16777619u;\n    }\n    return h;\n}\nvoid hmap_init(HMap *m) {\n    if (!m) return;\n    memset(m, 0, sizeof *m);\n}\nint hmap_put(HMap *m, const char *key, int value) {\n    if (!m || !key) return -1;\n    size_t b = fnv1a(key) % HMAP_BUCKETS;\n    HNode *n = malloc(sizeof *n);       /* wrong: allocates BEFORE checking\n                                             for an existing key -> duplicates */\n    if (!n) return -1;\n    n->key = key;\n    n->value = value;\n    n->next = m->buckets[b];\n    m->buckets[b] = n;\n    m->count++;\n    return 0;\n}\nint hmap_get(const HMap *m, const char *key, int *out) {\n    if (!m || !key || !out) return -1;\n    size_t b = fnv1a(key) % HMAP_BUCKETS;\n    for (const HNode *n = m->buckets[b]; n; n = n->next)\n        if (n->key == key) {            /* wrong: pointer identity, not strcmp \u2014\n                                             equal contents in different buffers miss */\n            *out = n->value;\n            return 0;\n        }\n    return -1;\n}\nint hmap_del(HMap *m, const char *key) {\n    if (!m || !key) return 0;\n    size_t b = fnv1a(key) % HMAP_BUCKETS;\n    for (HNode *n = m->buckets[b]; n; n = n->next) {\n        if (strcmp(n->key, key) == 0) {\n            free(n);                    /* wrong: previous node still points here */\n            m->count--;\n            return 1;\n        }\n    }\n    return 0;\n}\nsize_t hmap_size(const HMap *m) { return m ? m->count : 0; }\nsize_t hmap_max_chain(const HMap *m) {\n    if (!m) return 0;\n    size_t mx = 0;\n    for (size_t b = 0; b < HMAP_BUCKETS; b++) {\n        size_t len = 0;\n        for (const HNode *n = m->buckets[b]; n; n = n->next) len++;\n        if (len > mx) mx = len;\n    }\n    return mx;\n}\nvoid hmap_destroy(HMap *m) {\n    if (!m) return;\n    for (size_t b = 0; b < HMAP_BUCKETS; b++) {\n        HNode *n = m->buckets[b];\n        while (n) {\n            free(n);                    /* wrong: reads n->next after free */\n            n = n->next;\n        }\n        m->buckets[b] = NULL;\n    }\n    m->count = 0;\n}";
R["cint-checkpoint-m8-task"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\nstatic size_t fnv1a(const char *s) {\n    size_t h = 2166136261u;\n    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {\n        h ^= *p;\n        h *= 16777619u;\n    }\n    return h;\n}\nvoid wf_init(WF *w) {\n    if (!w) return;\n    memset(w, 0, sizeof *w);\n}\nint wf_count(WF *w, const char *word) {\n    if (!w || !word || !*word) return -1;\n    size_t b = fnv1a(word) % WF_BUCKETS;\n    for (WFNode *n = w->buckets[b]; n; n = n->next)\n        if (strcmp(n->word, word) == 0) {\n            n->count++;\n            return 0;\n        }\n    WFNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->word = malloc(strlen(word) + 1);\n    if (!n->word) {\n        free(n);\n        return -1;\n    }\n    strcpy((char *)n->word, word);\n    n->count = 1;\n    n->next = w->buckets[b];\n    w->buckets[b] = n;\n    w->distinct++;\n    return 0;\n}\nint wf_lookup(const WF *w, const char *word, size_t *count, const char **word_out) {\n    if (!w || !word || !count || !word_out) return -1;\n    size_t b = fnv1a(word) % WF_BUCKETS;\n    for (const WFNode *n = w->buckets[b]; n; n = n->next)\n        if (strcmp(n->word, word) == 0) {\n            *count = n->count;\n            *word_out = n->word;\n            return 1;\n        }\n    return 0;\n}\nsize_t wf_distinct(const WF *w) { return w ? w->distinct : 0; }\nvoid wf_destroy(WF *w) {\n    if (!w) return;\n    for (size_t b = 0; b < WF_BUCKETS; b++)\n        while (w->buckets[b]) {\n            WFNode *n = w->buckets[b];\n            w->buckets[b] = n->next;\n            free((char *)n->word);      /* key first \u2014 the node still names it */\n            free(n);\n        }\n    w->distinct = 0;\n}";
W["cint-checkpoint-m8-task"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\nstatic size_t fnv1a(const char *s) {\n    size_t h = 2166136261u;\n    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {\n        h ^= *p;\n        h *= 16777619u;\n    }\n    return h;\n}\nvoid wf_init(WF *w) {\n    if (!w) return;\n    memset(w, 0, sizeof *w);\n}\nint wf_count(WF *w, const char *word) {\n    if (!w || !word) return -1;         /* wrong: empty word accepted */\n    size_t b = fnv1a(word) % WF_BUCKETS;\n    for (WFNode *n = w->buckets[b]; n; n = n->next)\n        if (strcmp(n->word, word) == 0) {\n            n->count++;\n            return 0;\n        }\n    WFNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->word = word;                     /* wrong: stores the CALLER's pointer \u2014\n                                             the table does not own its key */\n    n->count = 1;\n    n->next = w->buckets[b];\n    w->buckets[b] = n;\n    w->distinct++;\n    return 0;\n}\nint wf_lookup(const WF *w, const char *word, size_t *count, const char **word_out) {\n    if (!w || !word || !count || !word_out) return -1;\n    size_t b = fnv1a(word) % WF_BUCKETS;\n    for (const WFNode *n = w->buckets[b]; n; n = n->next)\n        if (strcmp(n->word, word) == 0) {\n            *count = n->count;\n            *word_out = n->word;\n            return 1;\n        }\n    return 0;\n}\nsize_t wf_distinct(const WF *w) { return w ? w->distinct : 0; }\nvoid wf_destroy(WF *w) {\n    if (!w) return;\n    for (size_t b = 0; b < WF_BUCKETS; b++)\n        while (w->buckets[b]) {\n            WFNode *n = w->buckets[b];\n            w->buckets[b] = n->next;\n            free(n);                    /* wrong: key never freed (or double-freed\n                                             if the caller frees it) */\n        }\n    w->distinct = 0;\n}";
R["cint-p9-void-core"] = "\n#include <string.h>\n#include <stddef.h>\nvoid *g_lsearch(const void *key, const void *base, size_t n, size_t size,\n                int (*cmp)(const void *, const void *)) {\n    if (!key || !base || !cmp) return NULL;\n    const char *p = base;\n    for (size_t i = 0; i < n; i++, p += size)\n        if (cmp(key, p) == 0) return (void *)p;\n    return NULL;\n}\nvoid g_reverse(void *base, size_t n, size_t size) {\n    if (!base || n < 2) return;\n    char *lo = base, *hi = (char *)base + (n - 1) * size;\n    unsigned char tmp[64];\n    while (lo < hi) {\n        size_t k = size < sizeof tmp ? size : sizeof tmp;\n        /* element-sized swap via buffer; elements assumed <= 64 bytes here */\n        (void)k;\n        for (size_t b = 0; b < size; b++) {\n            char t = lo[b];\n            lo[b] = hi[b];\n            hi[b] = t;\n        }\n        lo += size;\n        hi -= size;\n    }\n}\nint g_has_dup(const void *base, size_t n, size_t size,\n              int (*cmp)(const void *, const void *)) {\n    if (!base || !cmp) return 0;\n    const char *p = base;\n    for (size_t i = 0; i < n; i++, p += size)\n        for (size_t j = i + 1; j < n; j++)\n            if (cmp(p, (const char *)base + j * size) == 0) return 1;\n    return 0;\n}";
W["cint-p9-void-core"] = "\n#include <string.h>\n#include <stddef.h>\nvoid *g_lsearch(const void *key, const void *base, size_t n, size_t size,\n                int (*cmp)(const void *, const void *)) {\n    if (!key || !base || !cmp) return NULL;\n    const char *p = base;\n    for (size_t i = 0; i < n; i++, p += size)\n        if (cmp(key, p) == 0) return (void *)p;\n    return NULL;\n}\nvoid g_reverse(void *base, size_t n, size_t size) {\n    if (!base || n < 2) return;\n    char *lo = base, *hi = (char *)base + (n - 1) * size;\n    while (lo < hi) {\n        lo = lo + size;      /* wrong: advances lo by one element but\n                                  never swaps \u2014 reverse does nothing */\n        hi = hi - size;\n    }\n}\nint g_has_dup(const void *base, size_t n, size_t size,\n              int (*cmp)(const void *, const void *)) {\n    if (!base || !cmp) return 0;\n    const char *p = base;\n    for (size_t i = 0; i < n; i++, p += size)\n        for (size_t j = 0; j < i; j++)         /* wrong: compares with EARLIER\n                                                      elements only up to i... but\n                                                      j goes 0..i which includes the\n                                                      element itself at j==i? no \u2014\n                                                      j < i so self-pair excluded;\n                                                      real defect: returns 1 for the\n                                                      FIRST pair even when none:\n                                                      missing equality check */\n            if (cmp(p, (const char *)base + j * size) == 0) return 1;\n    return 0;\n}";
R["cint-p9-qsort"] = "\n#include <stdlib.h>\n#include <stddef.h>\nvoid sort_ints(int *a, size_t n) {\n    if (!a) return;\n    qsort(a, n, sizeof *a, cmp_int);\n}\nlong find_int(const int *a, size_t n, int key) {\n    if (!a || n == 0) return -1;\n    const int *hit = bsearch(&key, a, n, sizeof *a, cmp_int);\n    return hit ? (long)(hit - a) : -1;\n}\nvoid sort_doubles(double *d, size_t n) {\n    if (!d) return;\n    qsort(d, n, sizeof *d, cmp_double);\n}";
W["cint-p9-qsort"] = "\n#include <stdlib.h>\n#include <stddef.h>\nvoid sort_ints(int *a, size_t n) {\n    if (!a) return;\n    qsort(a, n, sizeof(int), cmp_int);      /* fine */\n}\nlong find_int(const int *a, size_t n, int key) {\n    if (!a || n == 0) return -1;\n    const int *hit = bsearch(&key, a, n, sizeof(int), cmp_int);\n    return hit ? (long)(hit - a) : -1;\n}\nvoid sort_doubles(double *d, size_t n) {\n    if (!d) return;\n    qsort(d, n, sizeof *d, cmp_int);        /* wrong: int comparator on doubles \u2014\n                                                 reads 4 of the 8 bytes, garbage order */\n}";
R["cint-p9-typed-facade"] = "\n#define stack_push(st, val) _Generic((val), int: si_push, double: sd_push)((st), (val))\n#define stack_pop(st, out) _Generic((out), int *: si_pop, double *: sd_pop)((st), (out))";
W["cint-p9-typed-facade"] = "\n#define stack_push(st, val) _Generic((val), int: si_push, double: sd_push)((st), (val))\n#define stack_pop(st, out) (*(out) = 0, (st)->n--)   /* wrong: bypasses the typed\n                                                 functions \u2014 writes 0 instead of the\n                                                 popped value, returns the old count\n                                                 instead of 0/-1, and underflows n\n                                                 when empty */";
R["cint-checkpoint-m9-task"] = "\n#include <string.h>\n#include <stddef.h>\nstatic void swap_elems(char *a, char *b, size_t size) {\n    while (size--) {\n        char t = *a;\n        *a++ = *b;\n        *b++ = t;\n    }\n}\nvoid g_sort(void *base, size_t n, size_t size,\n            int (*cmp)(const void *, const void *)) {\n    if (!base || !cmp || n < 2) return;\n    char *b = base;\n    for (size_t i = 1; i < n; i++)           /* insertion sort via swaps */\n        for (size_t j = i; j > 0 &&\n             cmp(b + (j - 1) * size, b + j * size) > 0; j--)\n            swap_elems(b + (j - 1) * size, b + j * size, size);\n}\nsize_t g_dedup(void *base, size_t n, size_t size,\n               int (*cmp)(const void *, const void *)) {\n    if (!base || !cmp) return 0;\n    g_sort(base, n, size, cmp);              /* enforce the precondition */\n    char *wr = (char *)base + size;          /* element 0 already kept */\n    size_t m = 1;\n    for (size_t i = 1; i < n; i++) {\n        char *cur = (char *)base + i * size;\n        if (cmp(wr - size, cur) != 0) {      /* distinct from last KEPT */\n            if (wr != cur) memcpy(wr, cur, size);\n            wr += size;\n            m++;\n        }\n    }\n    return m;\n}";
W["cint-checkpoint-m9-task"] = "\n#include <string.h>\n#include <stddef.h>\nstatic void swap_miss(char *a, char *b, size_t size) { (void)a; (void)b; (void)size; }\nvoid g_sort(void *base, size_t n, size_t size,\n            int (*cmp)(const void *, const void *)) {\n    if (!base || !cmp || n < 2) return;\n    char *b = base;\n    for (size_t i = 1; i < n; i++)\n        for (size_t j = i; j > 0 &&\n             cmp(b + (j - 1) * size, b + j * size) > 0; j--)\n            swap_miss(b + (j - 1) * size, b + j * size, size);   /* wrong: the swap\n                                                  is a no-op \u2014 the sort never reorders,\n                                                  so both isort and dedup's internal\n                                                  sort leave data unsorted */\n}\nsize_t g_dedup(void *base, size_t n, size_t size,\n               int (*cmp)(const void *, const void *)) {\n    if (!base || !cmp) return 0;\n    g_sort(base, n, size, cmp);\n    char *rd = base, *wr = base;\n    size_t m = 1;\n    for (size_t i = 1; i < n; i++) {\n        char *cur = (char *)base + i * size;\n        if (cmp(rd, cur) != 0) {             /* wrong: compares against the READ\n                                                  cursor (last SEEN) instead of last\n                                                  KEPT \u2014 on input 1,1,2 it advances rd\n                                                  even for duplicates and can drop\n                                                  distinct elements */\n            rd = cur;\n            memcpy(wr, cur, size);\n            wr += size;\n            m++;\n        }\n        rd += size;\n    }\n    return m;\n}";
R["cint-p10-macro-write"] = "\n#include <stddef.h>\nlong sum_all(const int *a, size_t n) {\n    if (!a) return 0;\n    long s = 0;\n    for (size_t i = 0; i < n; i++) s += a[i];\n    return s;\n}\nint clamp(int v, int lo, int hi) {\n    if (lo > hi) return lo;                 /* degenerate range: pick lo */\n    int low = (v < lo) ? lo : v;            /* one side at a time avoids\n                                               double-evaluation surprises */\n    return (low > hi) ? hi : low;\n}";
W["cint-p10-macro-write"] = "\n#include <stddef.h>\nlong sum_all(const int *a, size_t n) {\n    if (!a) return 0;\n    return ARRAY_LEN(a) * n;                /* wrong: ARRAY_LEN on a pointer is\n                                                  sizeof(int*)/sizeof(int) == 2 on\n                                                  64-bit \u2014 garbage multiplied in */\n}\nint clamp(int v, int lo, int hi) {\n    return MAXI(lo, MAXI(v, hi));           /* wrong: MAX of all three \u2014 returns\n                                                  hi for in-range values */\n}";
R["cint-p10-xmacro"] = "\n#include <string.h>\n#include <stddef.h>\nint clr_from_name(const char *name) {\n    if (!name) return -1;\n    for (size_t i = 0; i < sizeof CLR_TAB / sizeof CLR_TAB[0]; i++)\n        if (strcmp(CLR_TAB[i].name, name) == 0) return (int)i;\n    return -1;\n}\nlong clr_hex(int clr) {\n    if (clr < 0 || (size_t)clr >= sizeof CLR_TAB / sizeof CLR_TAB[0]) return -1;\n    return CLR_TAB[clr].hex;\n}";
