R["cint-checkpoint-m10-task"] = "\n#include <limits.h>\n#include <string.h>\n#include <stddef.h>\nstatic const struct { const char *name; int code; } OP_NAMES[] = {\n#define X(id, code) { #id, code },\n    OPS\n#undef X\n};\nint op_apply(int op, int a, int b, int *out) {\n    if (!out) return -1;\n    long long r;\n    switch (op) {\n    case OP_ADD: r = (long long)a + b; break;\n    case OP_SUB: r = (long long)a - b; break;\n    case OP_MUL: r = (long long)a * b; break;\n    default: return -1;\n    }\n    if (r < INT_MIN || r > INT_MAX) return -1;\n    *out = (int)r;\n    return 0;\n}\nint op_from_name(const char *name) {\n    if (!name) return -1;\n    for (size_t i = 0; i < sizeof OP_NAMES / sizeof OP_NAMES[0]; i++)\n        if (strcmp(OP_NAMES[i].name, name) == 0) return OP_NAMES[i].code;\n    return -1;\n}";
W["cint-checkpoint-m10-task"] = "\n#include <limits.h>\n#include <string.h>\n#include <stddef.h>\nstatic const struct { const char *name; int code; } OP_NAMES[] = {\n#define X(id, code) { #id, code },\n    OPS\n#undef X\n};\nint op_apply(int op, int a, int b, int *out) {\n    if (!out) return -1;\n    int r;                                   /* wrong: int math \u2014 INT_MAX * 2\n                                                  is UB, not a detectable overflow */\n    switch (op) {\n    case OP_ADD: r = a + b; break;\n    case OP_SUB: r = a - b; break;\n    case OP_MUL: r = a * b; break;\n    default: return -1;\n    }\n    *out = r;\n    return 0;\n}\nint op_from_name(const char *name) {\n    if (!name) return -1;\n    for (size_t i = 0; i < sizeof OP_NAMES / sizeof OP_NAMES[0]; i++)\n        if (strstr(OP_NAMES[i].name, name) != NULL) return OP_NAMES[i].code;  /* wrong:\n                                                  substring match: \"A\" -> ADD, \"U\" -> SUB/MUL first hit */\n    return -1;\n}";
R["cint-p11-bst-core"] = "\n#include <stdlib.h>\n#include <stddef.h>\nint bst_insert(TNode **root, int v) {\n    if (!root) return -1;\n    TNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->value = v;\n    n->left = n->right = NULL;\n    TNode **link = root;\n    while (*link) {\n        if (v == (*link)->value) { free(n); return 1; }\n        link = (v < (*link)->value) ? &(*link)->left : &(*link)->right;\n    }\n    *link = n;\n    return 0;\n}\nint bst_find(const TNode *t, int v) {\n    while (t) {\n        if (v == t->value) return 1;\n        t = (v < t->value) ? t->left : t->right;\n    }\n    return 0;\n}\nsize_t bst_height(const TNode *t) {\n    if (!t) return 0;\n    size_t l = bst_height(t->left), r = bst_height(t->right);\n    return 1 + (l > r ? l : r);\n}\nlong bst_min(const TNode *t) {\n    if (!t) return LONG_MIN;\n    while (t->left) t = t->left;\n    return t->value;\n}\nstatic size_t inorder_rec(const TNode *t, int *out, size_t n) {\n    if (!t) return n;\n    n = inorder_rec(t->left, out, n);\n    out[n++] = t->value;\n    return inorder_rec(t->right, out, n);\n}\nsize_t bst_inorder(const TNode *root, int *out) {\n    if (!root || !out) return 0;\n    return inorder_rec(root, out, 0);\n}\nvoid bst_destroy(TNode *t) {\n    if (!t) return;\n    bst_destroy(t->left);\n    bst_destroy(t->right);\n    free(t);\n}";
W["cint-p11-bst-core"] = "\n#include <stdlib.h>\n#include <stddef.h>\nint bst_insert(TNode **root, int v) {\n    if (!root) return -1;\n    TNode *n = malloc(sizeof *n);\n    if (!n) return -1;\n    n->value = v;\n    n->left = n->right = NULL;\n    TNode *cur = *root;\n    while (cur) {\n        if (v == cur->value) { free(n); return 1; }\n        cur = (v < cur->value) ? cur->left : cur->right;\n    }\n    cur = n;                    /* wrong: assigns the LOCAL \u2014 nothing is attached */\n    return 0;\n}\nint bst_find(const TNode *t, int v) {\n    while (t) {\n        if (v == t->value) return 1;\n        t = (v < t->value) ? t->left : t->right;\n    }\n    return 0;\n}\nsize_t bst_height(const TNode *t) {\n    if (!t) return 0;\n    size_t l = bst_height(t->left), r = bst_height(t->right);\n    return 1 + (l > r ? l : r);\n}\nlong bst_min(const TNode *t) {\n    if (!t) return LONG_MIN;\n    while (t->right) t = t->right;   /* wrong: walks to the MAX */\n    return t->value;\n}\nstatic size_t inorder_rec(const TNode *t, int *out, size_t n) {\n    if (!t) return n;\n    n = inorder_rec(t->left, out, n);\n    out[n++] = t->value;\n    return inorder_rec(t->right, out, n);\n}\nsize_t bst_inorder(const TNode *root, int *out) {\n    if (!root || !out) return 0;\n    return inorder_rec(root, out, 0);\n}\nvoid bst_destroy(TNode *t) {\n    if (!t) return;\n    free(t);                    /* wrong: frees the parent first \u2014 children leak */\n    bst_destroy(t->left);\n    bst_destroy(t->right);\n}";
R["cint-p11-minheap"] = "\n#include <stddef.h>\nvoid heap_init(Heap *h) { if (h) h->n = 0; }\nint heap_push(Heap *h, long v) {\n    if (!h || h->n == HCAP) return -1;\n    size_t i = h->n++;\n    h->a[i] = v;\n    while (i > 0) {\n        size_t p = (i - 1) / 2;\n        if (h->a[p] <= h->a[i]) break;\n        long t = h->a[p]; h->a[p] = h->a[i]; h->a[i] = t;\n        i = p;\n    }\n    return 0;\n}\nint heap_pop(Heap *h, long *out) {\n    if (!h || !out || h->n == 0) return -1;\n    *out = h->a[0];\n    h->a[0] = h->a[--h->n];\n    size_t i = 0;\n    while (1) {\n        size_t l = 2*i + 1, r = 2*i + 2, smallest = i;\n        if (l < h->n && h->a[l] < h->a[smallest]) smallest = l;\n        if (r < h->n && h->a[r] < h->a[smallest]) smallest = r;\n        if (smallest == i) break;\n        long t = h->a[i]; h->a[i] = h->a[smallest]; h->a[smallest] = t;\n        i = smallest;\n    }\n    return 0;\n}\nint heap_peek(const Heap *h, long *out) {\n    if (!h || !out || h->n == 0) return -1;\n    *out = h->a[0];\n    return 0;\n}\nsize_t heap_size(const Heap *h) { return h ? h->n : 0; }\nint heap_ok(const Heap *h) {\n    if (!h) return 0;\n    for (size_t i = 1; i < h->n; i++)\n        if (h->a[(i - 1) / 2] > h->a[i]) return 0;\n    return 1;\n}";
W["cint-p11-minheap"] = "\n#include <stddef.h>\nvoid heap_init(Heap *h) { if (h) h->n = 0; }\nint heap_push(Heap *h, long v) {\n    if (!h || h->n == HCAP) return -1;\n    size_t i = h->n++;\n    h->a[i] = v;\n    while (i > 0) {\n        size_t p = (i - 1) / 2;\n        if (h->a[p] <= h->a[i]) break;\n        long t = h->a[p]; h->a[p] = h->a[i]; h->a[i] = t;\n        i = p;\n    }\n    return 0;\n}\nint heap_pop(Heap *h, long *out) {\n    if (!h || !out || h->n == 0) return -1;\n    *out = h->a[0];\n    h->a[0] = h->a[h->n - 1];\n    h->n--;                    /* fine so far */\n    size_t i = 0;\n    while (1) {\n        size_t l = 2*i + 1, r = 2*i + 2, smallest = i;\n        if (l < h->n && h->a[l] < h->a[smallest]) smallest = l;\n        if (r < h->n && h->a[r] < h->a[smallest]) smallest = r;\n        if (smallest == i) break;\n        long t = h->a[i]; h->a[i] = h->a[smallest]; h->a[smallest] = t;\n        i = l;                 /* wrong: descends LEFT regardless \u2014 with\n                                       r the smaller child the heap property\n                                       breaks and pop can return non-min */\n    }\n    return 0;\n}\nint heap_peek(const Heap *h, long *out) {\n    if (!h || !out || h->n == 0) return -1;\n    *out = h->a[0];\n    return 0;\n}\nsize_t heap_size(const Heap *h) { return h ? h->n : 0; }\nint heap_ok(const Heap *h) {\n    if (!h) return 0;\n    for (size_t i = 1; i < h->n; i++)\n        if (h->a[(i - 1) / 2] > h->a[i]) return 0;\n    return 1;\n}";
R["cint-p11-heapsort"] = "\n#include <stddef.h>\nstatic void sift_down_min(long *a, size_t n, size_t i) {\n    while (1) {\n        size_t l = 2*i + 1, r = 2*i + 2, smallest = i;\n        if (l < n && a[l] < a[smallest]) smallest = l;\n        if (r < n && a[r] < a[smallest]) smallest = r;\n        if (smallest == i) return;\n        long t = a[i]; a[i] = a[smallest]; a[smallest] = t;\n        i = smallest;\n    }\n}\nstatic void sift_down_max(long *a, size_t n, size_t i) {\n    while (1) {\n        size_t l = 2*i + 1, r = 2*i + 2, largest = i;\n        if (l < n && a[l] > a[largest]) largest = l;\n        if (r < n && a[r] > a[largest]) largest = r;\n        if (largest == i) return;\n        long t = a[i]; a[i] = a[largest]; a[largest] = t;\n        i = largest;\n    }\n}\nvoid heapify(long *a, size_t n) {\n    if (!a || n < 2) return;\n    for (size_t i = n / 2; i-- > 0;)\n        sift_down_min(a, n, i);\n}\nvoid heapsort_asc(long *a, size_t n) {\n    if (!a || n < 2) return;\n    for (size_t i = n / 2; i-- > 0;)\n        sift_down_max(a, n, i);\n    for (size_t end = n - 1; end > 0; end--) {\n        long t = a[0]; a[0] = a[end]; a[end] = t;\n        sift_down_max(a, end, 0);\n    }\n}";
W["cint-p11-heapsort"] = "\n#include <stddef.h>\nstatic void sift_down_min(long *a, size_t n, size_t i) {\n    while (1) {\n        size_t l = 2*i + 1, r = 2*i + 2, smallest = i;\n        if (l < n && a[l] < a[smallest]) smallest = l;\n        if (r < n && a[r] < a[smallest]) smallest = r;\n        if (smallest == i) return;\n        long t = a[i]; a[i] = a[smallest]; a[smallest] = t;\n        i = smallest;\n    }\n}\nvoid heapify(long *a, size_t n) {\n    if (!a || n < 2) return;\n    for (size_t i = 0; i < n; i++)          /* wrong: sift-down top-down from\n                                                  every index is not the O(n)\n                                                  build and \u2014 worse \u2014 descending\n                                                  order breaks the invariant it\n                                                  is meant to restore */\n        sift_down_min(a, n, i);\n}\nvoid heapsort_asc(long *a, size_t n) {\n    if (!a || n < 2) return;\n    heapify(a, n);                          /* wrong: builds a MIN-heap */\n    for (size_t end = n - 1; end > 0; end--) {\n        long t = a[0]; a[0] = a[end]; a[end] = t;\n        sift_down_min(a, end, 0);           /* wrong: min-heap swaps move the\n                                                  SMALLEST to the end \u2014 output\n                                                  is descending */\n    }\n}";
R["cint-checkpoint-m11-task"] = "\n#include <stddef.h>\nvoid tk_init(TopK *t) { if (t) t->n = 0; }\nstatic void sift_up(long *a, size_t i) {\n    while (i > 0) {\n        size_t p = (i - 1) / 2;\n        if (a[p] <= a[i]) break;\n        long t = a[p]; a[p] = a[i]; a[i] = t;\n        i = p;\n    }\n}\nstatic void sift_down(long *a, size_t n, size_t i) {\n    while (1) {\n        size_t l = 2*i + 1, r = 2*i + 2, smallest = i;\n        if (l < n && a[l] < a[smallest]) smallest = l;\n        if (r < n && a[r] < a[smallest]) smallest = r;\n        if (smallest == i) return;\n        long t = a[i]; a[i] = a[smallest]; a[smallest] = t;\n        i = smallest;\n    }\n}\nint tk_offer(TopK *t, long v) {\n    if (!t) return -1;\n    if (t->n < K) {\n        t->a[t->n++] = v;\n        sift_up(t->a, t->n - 1);\n        return 0;\n    }\n    if (v > t->a[0]) {                 /* beats the weakest survivor */\n        t->a[0] = v;\n        sift_down(t->a, t->n, 0);\n    }\n    return 0;                          /* else: discarded in O(1) */\n}\nsize_t tk_size(const TopK *t) { return t ? t->n : 0; }\nsize_t tk_report(const TopK *t, long *out) {\n    if (!t || !out) return 0;\n    for (size_t i = 0; i < t->n; i++) out[i] = t->a[i];\n    /* insertion sort descending \u2014 K <= 5 */\n    for (size_t i = 1; i < t->n; i++) {\n        long key = out[i];\n        size_t j = i;\n        while (j > 0 && out[j - 1] < key) {\n            out[j] = out[j - 1];\n            j--;\n        }\n        out[j] = key;\n    }\n    return t->n;\n}";
W["cint-checkpoint-m11-task"] = "\n#include <stddef.h>\nvoid tk_init(TopK *t) { if (t) t->n = 0; }\nint tk_offer(TopK *t, long v) {\n    if (!t) return -1;\n    if (t->n == K) return 0;           /* wrong: full -> always discard, even\n                                             when v beats the current minimum:\n                                             the true top-K is never tracked */\n    t->a[t->n++] = v;                  /* wrong: appended without sift-up \u2014\n                                             the min-heap property is not kept */\n    return 0;\n}\nsize_t tk_size(const TopK *t) { return t ? t->n : 0; }\nsize_t tk_report(const TopK *t, long *out) {\n    if (!t || !out) return 0;\n    for (size_t i = 0; i < t->n; i++) out[i] = t->a[i];\n    for (size_t i = 1; i < t->n; i++) {          /* ascending, not descending */\n        long key = out[i];\n        size_t j = i;\n        while (j > 0 && out[j - 1] > key) {\n            out[j] = out[j - 1];\n            j--;\n        }\n        out[j] = key;\n    }\n    return t->n;\n}";
R["cint-p12-csv-record"] = "\n#include <string.h>\n#include <stdio.h>\n#include <stddef.h>\n#include <stdint.h>\nstatic void put_u16le(unsigned char *b, unsigned v) {\n    b[0] = v & 0xFF; b[1] = (v >> 8) & 0xFF;\n}\nstatic void put_i32le(unsigned char *b, long v) {\n    b[0] = v & 0xFF; b[1] = (v >> 8) & 0xFF;\n    b[2] = (v >> 16) & 0xFF; b[3] = (v >> 24) & 0xFF;\n}\nstatic unsigned get_u16le(const unsigned char *b) {\n    return b[0] | ((unsigned)b[1] << 8);\n}\nstatic long get_i32le(const unsigned char *b) {\n    return (long)b[0] | ((long)b[1] << 8) | ((long)b[2] << 16) | ((long)b[3] << 24);\n}\nstatic size_t read_count(FILE *f) {\n    unsigned char b[2];\n    if (fseek(f, 4, SEEK_SET) != 0) return 0;\n    if (fread(b, 1, 2, f) != 2) return 0;\n    return get_u16le(b);\n}\nint rs_create(const char *path) {\n    if (!path) return -1;\n    FILE *f = fopen(path, \"wb\");\n    if (!f) return -1;\n    unsigned char hdr[6] = { 'C', 'J', 'R', '1', 0, 0 };\n    int ok = fwrite(hdr, 1, 6, f) == 6;\n    fclose(f);\n    return ok ? 0 : -1;\n}\nint rs_append(const char *path, unsigned id, int qty) {\n    if (!path || id > 255) return -1;\n    FILE *f = fopen(path, \"r+b\");\n    if (!f) return -1;\n    size_t n = read_count(f);\n    unsigned char rec[8] = {0};\n    rec[0] = (unsigned char)id;\n    put_i32le(&rec[1], qty);\n    int ok = fseek(f, (long)(6 + n * 8), SEEK_SET) == 0\n          && fwrite(rec, 1, 8, f) == 8;\n    if (ok) {\n        unsigned char cb[2];\n        put_u16le(cb, (unsigned)(n + 1));\n        ok = fseek(f, 4, SEEK_SET) == 0 && fwrite(cb, 1, 2, f) == 2;\n    }\n    fclose(f);\n    return ok ? 0 : -1;\n}\nint rs_read(const char *path, size_t index, unsigned *id, int *qty) {\n    if (!path) return -1;\n    FILE *f = fopen(path, \"rb\");\n    if (!f) return -1;\n    size_t n = read_count(f);\n    if (index >= n) { fclose(f); return -1; }\n    unsigned char rec[8];\n    int ok = fseek(f, (long)(6 + index * 8), SEEK_SET) == 0\n          && fread(rec, 1, 8, f) == 8;\n    fclose(f);\n    if (!ok) return -1;\n    if (id) *id = rec[0];\n    if (qty) *qty = (int)get_i32le(&rec[1]);\n    return 0;\n}\nsize_t rs_count(const char *path) {\n    if (!path) return 0;\n    FILE *f = fopen(path, \"rb\");\n    if (!f) return 0;\n    unsigned char hdr[4];\n    if (fread(hdr, 1, 4, f) != 4 || memcmp(hdr, \"CJR1\", 4) != 0) {\n        fclose(f);\n        return 0;\n    }\n    size_t n = read_count(f);\n    fclose(f);\n    return n;\n}";
W["cint-p12-csv-record"] = "\n#include <string.h>\n#include <stdio.h>\n#include <stddef.h>\n#include <stdint.h>\nstatic void put_u16le(unsigned char *b, unsigned v) {\n    b[0] = v & 0xFF; b[1] = (v >> 8) & 0xFF;\n}\nstatic void put_i32le(unsigned char *b, long v) {\n    b[0] = v & 0xFF; b[1] = (v >> 8) & 0xFF;\n    b[2] = (v >> 16) & 0xFF; b[3] = (v >> 24) & 0xFF;\n}\nstatic unsigned get_u16le(const unsigned char *b) {\n    return b[0] | ((unsigned)b[1] << 8);\n}\nstatic long get_i32le(const unsigned char *b) {\n    return (long)b[0] | ((long)b[1] << 8) | ((long)b[2] << 16) | ((long)b[3] << 24);\n}\nint rs_create(const char *path) {\n    if (!path) return -1;\n    FILE *f = fopen(path, \"wb\");\n    if (!f) return -1;\n    unsigned char hdr[6] = { 'C', 'J', 'R', '1', 0, 0 };\n    fwrite(hdr, 1, 6, f);\n    fclose(f);\n    return 0;\n}\nint rs_append(const char *path, unsigned id, int qty) {\n    if (!path) return -1;                     /* wrong: id > 255 accepted */\n    FILE *f = fopen(path, \"r+b\");\n    if (!f) return -1;\n    fseek(f, 0, SEEK_END);\n    unsigned char rec[8] = {0};\n    rec[0] = (unsigned char)id;\n    put_i32le(&rec[1], qty);\n    int ok = fwrite(rec, 1, 8, f) == 8;\n    long size = ftell(f);\n    unsigned char cb[2];\n    put_u16le(cb, (unsigned)((size - 6) / 8));\n    fseek(f, 4, SEEK_SET);\n    fwrite(cb, 1, 2, f);                      /* right idea, but... */\n    fclose(f);\n    (void)ok;\n    return 0;\n}\nint rs_read(const char *path, size_t index, unsigned *id, int *qty) {\n    if (!path) return -1;\n    FILE *f = fopen(path, \"rb\");\n    if (!f) return -1;\n    fseek(f, (long)(6 + index * 8), SEEK_SET);  /* wrong: no count check \u2014\n                                                  index past the end reads\n                                                  garbage or \"succeeds\" at EOF */\n    unsigned char rec[8];\n    size_t got = fread(rec, 1, 8, f);\n    fclose(f);\n    if (got != 8) return -1;\n    if (id) *id = rec[0];\n    if (qty) *qty = (int)get_i32le(&rec[1]);\n    return 0;\n}\nsize_t rs_count(const char *path) {\n    if (!path) return 0;\n    FILE *f = fopen(path, \"rb\");\n    if (!f) return 0;\n    fseek(f, 4, SEEK_SET);\n    unsigned char b[2];\n    fread(b, 1, 2, f);\n    fclose(f);\n    return get_u16le(b);                      /* wrong: no magic check */\n}";
R["cint-p12-blob"] = "\n#include <stdlib.h>\n#include <string.h>\n#include <stdio.h>\n#include <stddef.h>\n#include <stdint.h>\nstatic uint32_t fnv1a(const unsigned char *p, size_t n) {\n    uint32_t h = 2166136261u;\n    for (size_t i = 0; i < n; i++) {\n        h ^= p[i];\n        h *= 16777619u;\n    }\n    return h;\n}\nstatic void put_u32le(unsigned char *b, uint32_t v) {\n    b[0] = v & 0xFF; b[1] = (v >> 8) & 0xFF;\n    b[2] = (v >> 16) & 0xFF; b[3] = (v >> 24) & 0xFF;\n}\nstatic uint32_t get_u32le(const unsigned char *b) {\n    return (uint32_t)b[0] | ((uint32_t)b[1] << 8)\n         | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);\n}\nint blob_write(const char *path, const unsigned char *data, size_t len) {\n    if (!path || !data) return -1;\n    FILE *f = fopen(path, \"wb\");\n    if (!f) return -1;\n    unsigned char hdr[8] = { 'C', 'J', 'B', '1', 0, 0, 0, 0 };\n    put_u32le(&hdr[4], (uint32_t)len);\n    int ok = fwrite(hdr, 1, 8, f) == 8\n          && (len == 0 || fwrite(data, 1, len, f) == len);\n    if (ok) {\n        unsigned char ck[4];\n        put_u32le(ck, fnv1a(data, len));\n        ok = fwrite(ck, 1, 4, f) == 4;\n    }\n    fclose(f);\n    return ok ? 0 : -1;\n}\nint blob_read(const char *path, unsigned char **out, size_t *len) {\n    if (!path || !out || !len) return -1;\n    *out = NULL;\n    *len = 0;\n    FILE *f = fopen(path, \"rb\");\n    if (!f) return -1;\n    unsigned char hdr[8];\n    if (fread(hdr, 1, 8, f) != 8 || memcmp(hdr, \"CJB1\", 4) != 0) {\n        fclose(f);\n        return -1;\n    }\n    uint32_t n = get_u32le(&hdr[4]);\n    unsigned char *buf = malloc(n ? n : 1);\n    if (!buf) { fclose(f); return -1; }\n    if (fread(buf, 1, n, f) != n) {\n        free(buf);\n        fclose(f);\n        return -1;\n    }\n    unsigned char ck[4];\n    if (fread(ck, 1, 4, f) != 4 || get_u32le(ck) != fnv1a(buf, n)) {\n        free(buf);\n        fclose(f);\n        return -1;\n    }\n    fclose(f);\n    *out = buf;\n    *len = n;\n    return 0;\n}";
W["cint-p12-blob"] = "\n#include <stdlib.h>\n#include <string.h>\n#include <stdio.h>\n#include <stddef.h>\n#include <stdint.h>\nstatic uint32_t fnv1a(const unsigned char *p, size_t n) {\n    uint32_t h = 2166136261u;\n    for (size_t i = 0; i < n; i++) {\n        h ^= p[i];\n        h *= 16777619u;\n    }\n    return h;\n}\nstatic void put_u32le(unsigned char *b, uint32_t v) {\n    b[0] = v & 0xFF; b[1] = (v >> 8) & 0xFF;\n    b[2] = (v >> 16) & 0xFF; b[3] = (v >> 24) & 0xFF;\n}\nstatic uint32_t get_u32le(const unsigned char *b) {\n    return (uint32_t)b[0] | ((uint32_t)b[1] << 8)\n         | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);\n}\nint blob_write(const char *path, const unsigned char *data, size_t len) {\n    if (!path || !data) return -1;\n    FILE *f = fopen(path, \"wb\");\n    if (!f) return -1;\n    unsigned char hdr[8] = { 'C', 'J', 'B', '1', 0, 0, 0, 0 };\n    put_u32le(&hdr[4], (uint32_t)len);\n    fwrite(hdr, 1, 8, f);\n    fwrite(data, 1, len, f);\n    unsigned char ck[4];\n    put_u32le(ck, fnv1a(data, len));\n    fwrite(ck, 1, 4, f);\n    fclose(f);                                 /* wrong: no error checking on\n                                                  ANY write \u2014 disk-full silently\n                                                  produces a truncated file */\n    return 0;\n}\nint blob_read(const char *path, unsigned char **out, size_t *len) {\n    if (!path || !out || !len) return -1;\n    *out = NULL;\n    *len = 0;\n    FILE *f = fopen(path, \"rb\");\n    if (!f) return -1;\n    unsigned char hdr[8];\n    fread(hdr, 1, 8, f);                       /* wrong: count unchecked */\n    uint32_t n = get_u32le(&hdr[4]);\n    unsigned char *buf = malloc(n ? n : 1);\n    if (!buf) { fclose(f); return -1; }\n    fread(buf, 1, n, f);                       /* wrong: short read not detected */\n    fclose(f);\n    *out = buf;                                /* wrong: checksum never verified */\n    *len = n;\n    return 0;\n}";
R["cint-checkpoint-m12-task"] = "\n#include <string.h>\n#include <stdio.h>\n#include <stddef.h>\nlong db_load(const char *path, unsigned char *out, size_t cap) {\n    if (!path || !out || cap == 0) return -1;\n    FILE *f = fopen(path, \"rb\");\n    if (!f) return -1;\n    unsigned char hdr[6];\n    if (fread(hdr, 1, 6, f) != 6 || memcmp(hdr, \"CJR1\", 4) != 0) {\n        fclose(f);\n        return -1;\n    }\n    size_t claimed = hdr[4] | ((size_t)hdr[5] << 8);\n    long loaded = 0;\n    for (size_t i = 0; i < claimed && loaded < (long)cap; i++) {\n        unsigned char rec[8];\n        if (fread(rec, 1, 8, f) != 8) break;   /* truncated: stop cleanly */\n        memcpy(out + (size_t)loaded * 8, rec, 8);\n        loaded++;\n    }\n    fclose(f);\n    return loaded;\n}";
W["cint-checkpoint-m12-task"] = "\n#include <string.h>\n#include <stdio.h>\n#include <stddef.h>\nlong db_load(const char *path, unsigned char *out, size_t cap) {\n    if (!path || !out) return -1;              /* wrong: cap == 0 passes */\n    FILE *f = fopen(path, \"rb\");\n    if (!f) return -1;\n    unsigned char hdr[6];\n    fread(hdr, 1, 6, f);                       /* wrong: count unchecked \u2014\n                                                  a 3-byte file \"reads\" a header */\n    if (memcmp(hdr, \"CJR1\", 4) != 0) {\n        fclose(f);\n        return -1;\n    }\n    size_t claimed = hdr[4] | ((size_t)hdr[5] << 8);\n    if (claimed > cap) claimed = cap;          /* fine, but see below */\n    for (size_t i = 0; i < claimed; i++) {\n        unsigned char rec[8];\n        fread(rec, 1, 8, f);                   /* wrong: short read ignored \u2014\n                                                  the tail of a truncated file\n                                                  is filled with garbage and\n                                                  reported as valid records */\n        memcpy(out + i * 8, rec, 8);\n    }\n    fclose(f);\n    return (long)claimed;\n}";
R["cint-p13-threeval"] = "\n#include <string.h>\n#include <stddef.h>\nvoid tab_init(Table *t) {\n    if (!t) return;\n    memset(t, 0, sizeof *t);\n}\nint tab_put(Table *t, long k, long v) {\n    if (!t || t->n == 16) return -1;\n    for (size_t i = 0; i < t->n; i++)\n        if (t->keys[i] == k) { t->vals[i] = v; return 0; }\n    t->keys[t->n] = k;\n    t->vals[t->n] = v;\n    t->n++;\n    return 0;\n}\nint tab_get(const Table *t, long k, long *out) {\n    if (!t || !out) return LOOKUP_ERROR;\n    for (size_t i = 0; i < t->n; i++)\n        if (t->keys[i] == k) { *out = t->vals[i]; return LOOKUP_FOUND; }\n    return LOOKUP_ABSENT;\n}\nint tab_del(Table *t, long k) {\n    if (!t) return -1;\n    for (size_t i = 0; i < t->n; i++)\n        if (t->keys[i] == k) {\n            t->keys[i] = t->keys[t->n - 1];\n            t->vals[i] = t->vals[t->n - 1];\n            t->n--;\n            return 1;\n        }\n    return 0;\n}";
W["cint-p13-threeval"] = "\n#include <string.h>\n#include <stddef.h>\nvoid tab_init(Table *t) {\n    if (!t) return;\n    memset(t, 0, sizeof *t);\n}\nint tab_put(Table *t, long k, long v) {\n    if (!t || t->n == 16) return -1;\n    t->keys[t->n] = k;\n    t->vals[t->n] = v;\n    t->n++;\n    return 0;                     /* wrong: duplicate keys pile up \u2014\n                                       get returns whichever copy it meets */\n}\nint tab_get(const Table *t, long k, long *out) {\n    if (!t) return LOOKUP_ABSENT;   /* wrong: bad ARGS reported as ABSENT */\n    if (!out) return LOOKUP_ERROR;\n    for (size_t i = 0; i < t->n; i++)\n        if (t->keys[i] == k) { *out = t->vals[i]; return LOOKUP_FOUND; }\n    return LOOKUP_ABSENT;\n}\nint tab_del(Table *t, long k) {\n    if (!t) return 0;             /* wrong: NULL t is an error, not \"absent\" */\n    for (size_t i = 0; i < t->n; i++)\n        if (t->keys[i] == k) {\n            t->n--;               /* wrong: leaves the deleted key in place\n                                       and shifts nothing \u2014 later puts\n                                       overwrite live entries */\n            return 1;\n        }\n    return 0;\n}";
R["cint-p13-cleanup"] = "\nint pipeline(int fail_at) {\n    int a1 = 0, a2 = 0, a3 = 0;\n    int rc = -1;\n    if (fail_at == 1) goto cleanup;\n    if (tr_acquire(1) != 0) goto cleanup;\n    a1 = 1;\n    if (fail_at == 2) goto cleanup;\n    if (tr_acquire(2) != 0) goto cleanup;\n    a2 = 1;\n    if (fail_at == 3) goto cleanup;\n    if (tr_acquire(3) != 0) goto cleanup;\n    a3 = 1;\n    rc = 0;                        /* the work */\ncleanup:\n    if (a3) tr_release(3);\n    if (a2) tr_release(2);\n    if (a1) tr_release(1);\n    return rc;\n}";
W["cint-p13-cleanup"] = "\nint pipeline(int fail_at) {\n    if (fail_at == 1) return -1;\n    if (tr_acquire(1) != 0) return -1;\n    if (fail_at == 2) return -1;   /* wrong: 1 never released */\n    if (tr_acquire(2) != 0) { tr_release(1); return -1; }\n    if (fail_at == 3) return -1;   /* wrong: 1 and 2 never released */\n    if (tr_acquire(3) != 0) { tr_release(2); tr_release(1); return -1; }\n    tr_release(3);\n    tr_release(2);\n    tr_release(1);\n    return 0;\n}";
R["cint-p13-two-phase"] = "\n#include <string.h>\n#include <stddef.h>\nint conn_init(Conn *c) {\n    if (!c) return -1;\n    memset(c, 0, sizeof *c);\n    c->state = C_READY;\n    return 0;\n}\nint conn_connect(Conn *c, const char *target) {\n    if (!c) return -1;\n    c->attempts++;\n    if (!target || !*target || strlen(target) >= 32) {\n        c->state = C_FAILED;\n        return -1;\n    }\n    snprintf(c->target, sizeof c->target, \"%s\", target);\n    c->state = C_CONNECTED;\n    return 0;\n}\nvoid conn_close(Conn *c) {\n    if (!c) return;\n    if (c->state == C_CONNECTED || c->state == C_FAILED)\n        c->state = C_READY;\n}\nint conn_destroy(Conn *c) {\n    if (!c) return -1;\n    c->state = C_NEW;\n    return 0;\n}";
W["cint-p13-two-phase"] = "\n#include <string.h>\n#include <stddef.h>\nint conn_init(Conn *c) {\n    if (!c) return -1;\n    memset(c, 0, sizeof *c);\n    c->state = C_READY;\n    return 0;\n}\nint conn_connect(Conn *c, const char *target) {\n    if (!c) return -1;\n    if (!target || !*target || strlen(target) >= 32) {\n        c->state = C_FAILED;\n        return -1;                 /* wrong: attempts not counted */\n    }\n    snprintf(c->target, sizeof c->target, \"%s\", target);\n    c->state = C_CONNECTED;\n    return 0;\n}\nvoid conn_close(Conn *c) {\n    if (!c) return;\n    c->state = C_READY;            /* wrong: closes from NEW too \u2014\n                                       invents a state transition that\n                                       never happened */\n}\nint conn_destroy(Conn *c) {\n    if (!c) return -1;\n    if (c->state == C_CONNECTED) return -1;   /* wrong: destroy refuses a\n                                                  valid state \u2014 leaks the object */\n    c->state = C_NEW;\n    return 0;\n}";
R["cint-checkpoint-m13-task"] = "\n#include <stdio.h>\n#include <string.h>\n#include <stddef.h>\nint cfg_stage(const char *input, char *report, size_t cap) {\n    if (!input || !report || cap == 0) return -1;\n    report[0] = '\\0';\n    const char *p = input;\n    int pairs = 0;\n    while (*p) {\n        const char *eq = strchr(p, '=');\n        const char *eol = strchr(p, '\\n');\n        size_t linelen = eol ? (size_t)(eol - p) : strlen(p);\n        if (!eq || (eol && eq > eol) || eq == p) {\n            snprintf(report, cap, \"config: line %d lacks key=value\", pairs + 1);\n            return -1;\n        }\n        pairs++;\n        if (!eol) break;\n        p = eol + 1;\n    }\n    if (pairs == 0) {\n        snprintf(report, cap, \"config: empty\");\n        return -1;\n    }\n    snprintf(report, cap, \"config: ok (%d pairs)\", pairs);\n    return 0;\n}\nint data_stage(const char *input, long *total, char *report, size_t cap) {\n    if (!input || !total || !report || cap == 0) return -1;\n    report[0] = '\\0';\n    long sum = 0;\n    const char *p = input;\n    int lines = 0;\n    while (*p) {\n        const char *eol = strchr(p, '\\n');\n        size_t linelen = eol ? (size_t)(eol - p) : strlen(p);\n        if (linelen == 0) {\n            snprintf(report, cap, \"data: empty line %d\", lines + 1);\n            return -1;\n        }\n        long v = 0;\n        for (size_t i = 0; i < linelen; i++) {\n            if (p[i] < '0' || p[i] > '9') {\n                snprintf(report, cap, \"data: line %d not a nonneg int\", lines + 1);\n                return -1;\n            }\n            v = v * 10 + (p[i] - '0');\n            if (v > 1000000000L) {\n                snprintf(report, cap, \"data: line %d too large\", lines + 1);\n                return -1;\n            }\n        }\n        sum += v;\n        lines++;\n        if (!eol) break;\n        p = eol + 1;\n    }\n    *total = sum;\n    snprintf(report, cap, \"data: ok (%d lines, total %ld)\", lines, sum);\n    return 0;\n}\nint app_run(const char *cfg_in, const char *data_in, char *report, size_t cap) {\n    if (!report || cap == 0) return APP_EARGS;\n    report[0] = '\\0';\n    if (!cfg_in) return APP_ECONFIG;\n    if (!data_in) return APP_EDATA;\n    char stage[64];\n    if (cfg_stage(cfg_in, stage, sizeof stage) != 0) {\n        snprintf(report, cap, \"%s\", stage);\n        return APP_ECONFIG;\n    }\n    long total = 0;\n    if (data_stage(data_in, &total, stage, sizeof stage) != 0) {\n        snprintf(report, cap, \"%s\", stage);\n        return APP_EDATA;\n    }\n    snprintf(report, cap, \"%s | %s\", \"ok\", stage);\n    return APP_OK;\n}";
W["cint-checkpoint-m13-task"] = "\n#include <stdio.h>\n#include <string.h>\n#include <stddef.h>\nint cfg_stage(const char *input, char *report, size_t cap) {\n    if (!input || !report || cap == 0) return -1;\n    report[0] = '\\0';\n    const char *eq = strchr(input, '=');\n    if (!eq) {\n        snprintf(report, cap, \"config: bad\");\n        return -1;\n    }\n    snprintf(report, cap, \"config: ok\");\n    return 0;                    /* wrong: only checks the FIRST line \u2014\n                                       \"a=1\\nnoequals\" wrongly passes */\n}\nint data_stage(const char *input, long *total, char *report, size_t cap) {\n    if (!input || !total || !report || cap == 0) return -1;\n    report[0] = '\\0';\n    *total = 0;\n    const char *p = input;\n    while (*p) {\n        if (*p == '\\n') { p++; continue; }\n        if (*p == '-') {         /* wrong: '-' skipped silently \u2014 negatives\n                                       accepted into a nonneg sum */\n            p++;\n            continue;\n        }\n        if (*p < '0' || *p > '9') {\n            snprintf(report, cap, \"data: bad\");\n            return -1;\n        }\n        *total = *total * 10 + (*p - '0');   /* wrong: accumulates digits\n                                                  across lines without line\n                                                  boundaries */\n        p++;\n    }\n    snprintf(report, cap, \"data: ok\");\n    return 0;\n}\nint app_run(const char *cfg_in, const char *data_in, char *report, size_t cap) {\n    if (!report || cap == 0) return APP_EARGS;\n    report[0] = '\\0';\n    char stage[64];\n    if (cfg_stage(cfg_in, stage, sizeof stage) != 0\n        || data_stage(data_in, &stage[0] != NULL ? stage : stage, sizeof stage) != 0)\n        return APP_ECONFIG;      /* wrong: BOTH failures reported as config \u2014\n                                       data failures are indistinguishable */\n    snprintf(report, cap, \"%s\", stage);\n    return APP_OK;\n}";
R["cint-p14-saturate"] = "\n#include <limits.h>\nint sat_add(int a, int b) {\n    long long r = (long long)a + b;\n    if (r > INT_MAX) return INT_MAX;\n    if (r < INT_MIN) return INT_MIN;\n    return (int)r;\n}\nint sat_sub(int a, int b) {\n    long long r = (long long)a - b;\n    if (r > INT_MAX) return INT_MAX;\n    if (r < INT_MIN) return INT_MIN;\n    return (int)r;\n}\nint sat_mul(int a, int b) {\n    long long r = (long long)a * b;\n    if (r > INT_MAX) return INT_MAX;\n    if (r < INT_MIN) return INT_MIN;\n    return (int)r;\n}\nunsigned safe_shl(unsigned x, unsigned k) {\n    if (k >= 32) return 0;\n    return x << k;\n}";
W["cint-p14-saturate"] = "\n#include <limits.h>\nint sat_add(int a, int b) {\n    if (a > 0 && b > INT_MAX - a) return INT_MAX;   /* fine... */\n    if (a < 0 && b < INT_MIN - a) return INT_MIN;\n    return a + b;\n}\nint sat_sub(int a, int b) {\n    long long r = (long long)a - b;\n    if (r > INT_MAX) return INT_MAX;\n    if (r < INT_MIN) return INT_MIN;\n    return (int)r;\n}\nint sat_mul(int a, int b) {\n    return a * b;              /* wrong: the multiply itself overflows\n                                       before any check could run \u2014 the\n                                       exact bug the lesson forbids */\n}\nunsigned safe_shl(unsigned x, unsigned k) {\n    return x << (k & 31);      /* wrong: silently wraps k (shift 32\n                                       becomes shift 0 \u2014 a wrong answer\n                                       dressed as success) */\n}";
R["cint-p14-bounded-api"] = "\n#include <string.h>\n#include <stddef.h>\nint str_copy_bounded(char *dst, size_t dstcap, const char *src) {\n    if (!dst || dstcap == 0 || !src) return -1;\n    size_t i = 0;\n    while (i + 1 < dstcap && src[i] != '\\0') {\n        dst[i] = src[i];\n        i++;\n    }\n    dst[i] = '\\0';\n    return (int)i;                 /* copied count; caller sees short copy */\n}\nint num_parse_bounded(const char *s, long lo, long hi, long *out) {\n    if (!s || !out || !*s) return -1;\n    int neg = 0;\n    const char *p = s;\n    if (*p == '-') { neg = 1; p++; if (!*p) return -1; }\n    if (*p < '0' || *p > '9') return -1;\n    long v = 0;\n    int digits = 0;\n    for (; *p; p++, digits++) {\n        if (*p < '0' || *p > '9') return -1;\n        if (digits >= 18) return -1;         /* 18 digits: can't overflow long */\n        v = v * 10 + (*p - '0');\n    }\n    if (neg) v = -v;\n    if (v < lo || v > hi) return -1;\n    *out = v;\n    return 0;\n}\nint region_zero(const unsigned char *p, size_t n) {\n    if (!p) return n == 0 ? 0 : -1;\n    for (size_t i = 0; i < n; i++)\n        if (p[i] != 0) return 0;\n    return 1;\n}";
W["cint-p14-bounded-api"] = "\n#include <string.h>\n#include <stdlib.h>\n#include <stddef.h>\nint str_copy_bounded(char *dst, size_t dstcap, const char *src) {\n    if (!dst || dstcap == 0 || !src) return -1;\n    strncpy(dst, src, dstcap);   /* wrong: strncpy does NOT terminate when\n                                       src fills the cap \u2014 caller's buffer\n                                       left unterminated */\n    return (int)strlen(src);\n}\nint num_parse_bounded(const char *s, long lo, long hi, long *out) {\n    if (!s || !out || !*s) return -1;\n    *out = atol(s);              /* wrong: atol accepts \"12x\" and overflows\n                                       silently far outside [lo,hi] */\n    if (*out < lo || *out > hi) return -1;\n    return 0;\n}\nint region_zero(const unsigned char *p, size_t n) {\n    if (!p) return 0;            /* wrong: n > 0 with NULL p is an error,\n                                       not \"nothing to check\" */\n    for (size_t i = 0; i < n; i++)\n        if (p[i] != 0) return 0;\n    return 1;\n}";
R["cint-checkpoint-m14-task"] = "\n#include <string.h>\n#include <limits.h>\n#include <stddef.h>\nint sat_add2(int a, int b) {\n    long long r = (long long)a + b;\n    if (r > INT_MAX) return INT_MAX;\n    if (r < INT_MIN) return INT_MIN;\n    return (int)r;\n}\nint sat_mul2(int a, int b) {\n    long long r = (long long)a * b;\n    if (r > INT_MAX) return INT_MAX;\n    if (r < INT_MIN) return INT_MIN;\n    return (int)r;\n}\nstatic int parse_uint(const char *s, size_t len, int *out) {\n    if (len == 0 || len > 10) return -1;\n    long v = 0;\n    for (size_t i = 0; i < len; i++) {\n        if (s[i] < '0' || s[i] > '9') return -1;\n        v = v * 10 + (s[i] - '0');\n    }\n    if (v > INT_MAX) return -1;\n    *out = (int)v;\n    return 0;\n}\nint eval_expr(const char *s, int *out) {\n    if (!s || !out) return -1;\n    int a, b;\n    char op = 0;\n    size_t i = 0;\n    while (s[i] == ' ') i++;\n    size_t start = i;\n    while (s[i] && s[i] != ' ' && s[i] != '+' && s[i] != '-' && s[i] != '*') i++;\n    if (parse_uint(s + start, i - start, &a) != 0) return -1;\n    while (s[i] == ' ') i++;\n    if (s[i] != '+' && s[i] != '-' && s[i] != '*') return -1;\n    op = s[i++];\n    while (s[i] == ' ') i++;\n    start = i;\n    while (s[i] && s[i] != ' ' && s[i] != '+' && s[i] != '-' && s[i] != '*') i++;\n    if (parse_uint(s + start, i - start, &b) != 0) return -1;\n    while (s[i] == ' ') i++;\n    if (s[i] != '\\0') return -1;               /* trailing junk */\n    if (op == '+') { *out = sat_add2(a, b); return 0; }\n    if (op == '-') { *out = sat_add2(a, -b); return 0; }   /* -b: b <= INT_MAX,\n                                                  so -b overflows only when\n                                                  b == INT_MIN \u2014 impossible\n                                                  here since b >= 0 */\n    *out = sat_mul2(a, b);\n    return 0;\n}";
W["cint-checkpoint-m14-task"] = "\n#include <string.h>\n#include <limits.h>\n#include <stdlib.h>\n#include <stddef.h>\nint sat_add2(int a, int b) {\n    return a + b;                /* wrong: signed overflow IS the operation \u2014\n                                       undefined, not saturating */\n}\nint sat_mul2(int a, int b) {\n    return a * b;                /* wrong: same */\n}\nint eval_expr(const char *s, int *out) {\n    if (!s || !out) return -1;\n    int a = atoi(s);             /* wrong: atoi stops at the op, accepts\n                                       \"12x\", overflows silently */\n    while (*s >= '0' && *s <= '9') s++;\n    while (*s == ' ') s++;\n    char op = *s++;\n    while (*s == ' ') s++;\n    int b = atoi(s);\n    switch (op) {\n    case '+': *out = a + b; return 0;      /* wrong: UB on overflow */\n    case '-': *out = a - b; return 0;\n    case '*': *out = a * b; return 0;\n    default: return -1;\n    }\n}";
R["cint-p15-counters"] = "\n#include <threads.h>\n#include <stddef.h>\n#define MAXW 16\ntypedef struct { int per; } WArg;\nstatic WArg g_args[MAXW];\nstatic thrd_t g_ts[MAXW];\nstatic int worker(void *p) {\n    WArg *a = p;\n    inc_n_times(a->per);\n    return 0;\n}\nint run_workers(int workers, int per_thread) {\n    if (workers < 0 || workers > MAXW || per_thread < 0) return -1;\n    for (int i = 0; i < workers; i++) {\n        g_args[i].per = per_thread;\n        if (thrd_create(&g_ts[i], worker, &g_args[i]) != thrd_success)\n            return -1;\n    }\n    for (int i = 0; i < workers; i++) {\n        int rc;\n        if (thrd_join(g_ts[i], &rc) != thrd_success) return -1;\n    }\n    return 0;\n}";
W["cint-p15-counters"] = "\n#include <threads.h>\n#include <stddef.h>\n#define MAXW 16\ntypedef struct { int per; } WArg;\nstatic WArg g_args[MAXW];\nstatic thrd_t g_ts[MAXW];\nstatic int worker(void *p) {\n    WArg *a = p;\n    inc_n_times(a->per);\n    return 0;\n}\nint run_workers(int workers, int per_thread) {\n    if (workers < 0 || workers > MAXW || per_thread < 0) return -1;\n    for (int i = 0; i < workers; i++) {\n        g_args[i].per = per_thread;\n        if (thrd_create(&g_ts[i], worker, &g_args[i]) != thrd_success)\n            return -1;\n    }\n    for (int i = 0; i < workers - 1; i++) {   /* wrong: never joins the LAST\n                                          worker \u2014 main may race ahead of its\n                                          final increments, so the total is\n                                          short by up to per_thread */\n        int rc;\n        thrd_join(g_ts[i], &rc);\n    }\n    return 0;\n}";
R["cint-p15-bounded-queue"] = "\n#include <threads.h>\n#include <stddef.h>\nvoid bq_init(BQ *q) {\n    if (!q) return;\n    q->head = 0;\n    q->count = 0;\n    mtx_init(&q->m, mtx_plain);\n    cnd_init(&q->not_full);\n    cnd_init(&q->not_empty);\n}\nvoid bq_destroy(BQ *q) {\n    if (!q) return;\n    mtx_destroy(&q->m);\n    cnd_destroy(&q->not_full);\n    cnd_destroy(&q->not_empty);\n}\nint bq_push(BQ *q, long v) {\n    if (!q) return -1;\n    mtx_lock(&q->m);\n    while (q->count == QCAP)\n        cnd_wait(&q->not_full, &q->m);\n    q->items[(q->head + q->count) % QCAP] = v;\n    q->count++;\n    cnd_signal(&q->not_empty);\n    mtx_unlock(&q->m);\n    return 0;\n}\nint bq_pop(BQ *q, long *out) {\n    if (!q || !out) return -1;\n    mtx_lock(&q->m);\n    while (q->count == 0)\n        cnd_wait(&q->not_empty, &q->m);\n    *out = q->items[q->head];\n    q->head = (q->head + 1) % QCAP;\n    q->count--;\n    cnd_signal(&q->not_full);\n    mtx_unlock(&q->m);\n    return 0;\n}\nsize_t bq_count(BQ *q) {\n    if (!q) return 0;\n    mtx_lock(&q->m);\n    size_t n = q->count;\n    mtx_unlock(&q->m);\n    return n;\n}";
W["cint-p15-bounded-queue"] = "\n#include <threads.h>\n#include <stddef.h>\nvoid bq_init(BQ *q) {\n    if (!q) return;\n    q->head = 0;\n    q->count = 0;\n    mtx_init(&q->m, mtx_plain);\n    cnd_init(&q->not_full);\n    cnd_init(&q->not_empty);\n}\nvoid bq_destroy(BQ *q) {\n    if (!q) return;\n    mtx_destroy(&q->m);\n    cnd_destroy(&q->not_full);\n    cnd_destroy(&q->not_empty);\n}\nint bq_push(BQ *q, long v) {\n    if (!q) return -1;\n    mtx_lock(&q->m);\n    q->items[q->head] = v;         /* wrong: stores at head \u2014 the oldest\n                                          slot \u2014 instead of the tail; with a\n                                          full ring this OVERWRITES the oldest\n                                          value, so FIFO order is destroyed\n                                          deterministically */\n    q->head = (q->head + 1) % QCAP;\n    if (q->count < QCAP) q->count++;\n    cnd_signal(&q->not_empty);\n    mtx_unlock(&q->m);\n    return 0;\n}\nint bq_pop(BQ *q, long *out) {\n    if (!q || !out) return -1;\n    mtx_lock(&q->m);\n    if (q->count == 0) {           /* wrong: IF, not WHILE \u2014 a spurious\n                                          wakeup pops garbage; also returns\n                                          WITHOUT unlocking on this path */\n        return -1;\n    }\n    q->head = (q->head + 1) % QCAP;   /* wrong: advances head BEFORE reading \u2014\n                                          pops return the NEXT element, so\n                                          the first pop loses the oldest */\n    *out = q->items[q->head];\n    q->count--;\n    cnd_signal(&q->not_full);\n    mtx_unlock(&q->m);\n    return 0;\n}\nsize_t bq_count(BQ *q) {\n    if (!q) return 0;\n    return q->count;               /* wrong: unlocked read \u2014 fine when no\n                                       workers run, but the contract here\n                                       is a locked read */\n}";
R["cint-checkpoint-m15-task"] = "\n#include <threads.h>\n#include <stddef.h>\nint producer_body(BQ *q, int n) {\n    if (!q || n < 0) return -1;\n    for (int i = 0; i < n; i++)\n        if (bq_ref_push(q, i) != 0) return -1;\n    mtx_lock(&done_m);\n    producers_done++;\n    cnd_broadcast(&done_cv);\n    mtx_unlock(&done_m);\n    return 0;\n}\nint consumer_body(BQ *q, int expected, long *sum) {\n    if (!q || !sum || expected < 0) return -1;\n    long acc = 0;\n    for (int i = 0; i < expected; i++) {\n        long v;\n        if (bq_ref_pop(q, &v) != 0) return -1;\n        acc += v;\n    }\n    *sum = acc;\n    return 0;\n}";
W["cint-checkpoint-m15-task"] = "\n#include <threads.h>\n#include <stddef.h>\nint producer_body(BQ *q, int n) {\n    if (!q || n < 0) return -1;\n    for (int i = 0; i < n; i++)\n        if (bq_ref_push(q, i) != 0) return -1;\n    return 0;                      /* wrong: never signals producers_done */\n}\nint consumer_body(BQ *q, int expected, long *sum) {\n    if (!q || !sum || expected < 0) return -1;\n    mtx_lock(&done_m);\n    int done = producers_done > 0;   /* wrong: reads the latch ONCE, before\n                                          the producer can finish \u2014 and since\n                                          this consumer never pops, the\n                                          producer blocks on the full queue\n                                          and can NEVER signal. Deterministic\n                                          deadlock of intent. */\n    mtx_unlock(&done_m);\n    if (!done) {\n        *sum = -1;\n        return 0;\n    }\n    long acc = 0;\n    for (int i = 0; i < expected; i++) {\n        long v;\n        if (bq_ref_pop(q, &v) != 0) return -1;\n        acc += v;\n    }\n    *sum = acc;\n    return 0;\n}";
R["cint-p16-kvcore"] = "\nvoid kv_init(KVStore *s) {\n    if (!s) return;\n    memset(s, 0, sizeof *s);\n}\nstatic size_t kv_find(const KVStore *s, const char *key) {\n    for (size_t i = 0; i < KV_CAP; i++)\n        if (s->slots[i].live && strncmp(s->slots[i].key, key, KV_KEYMAX) == 0)\n            return i;\n    return KV_CAP;\n}\nKVError kv_put(KVStore *s, const char *key, long value) {\n    if (!s || !key) return KV_EARGS;\n    size_t at = kv_find(s, key);\n    if (at < KV_CAP) { s->slots[at].value = value; return KV_OK; }\n    for (size_t i = 0; i < KV_CAP; i++) {\n        if (!s->slots[i].live) {\n            memset(s->slots[i].key, 0, KV_KEYMAX);        /* own the bytes */\n            strncpy(s->slots[i].key, key, KV_KEYMAX - 1);\n            s->slots[i].value = value;\n            s->slots[i].live = 1;\n            s->count++;\n            return KV_OK;\n        }\n    }\n    return KV_ENOMEM;                                     /* state unchanged */\n}\nKVError kv_get(const KVStore *s, const char *key, long *out) {\n    if (!s || !key || !out) return KV_EARGS;\n    size_t at = kv_find(s, key);\n    if (at == KV_CAP) return KV_ENOENT;\n    *out = s->slots[at].value;\n    return KV_OK;\n}\nKVError kv_del(KVStore *s, const char *key) {\n    if (!s || !key) return KV_EARGS;\n    size_t at = kv_find(s, key);\n    if (at == KV_CAP) return KV_ENOENT;\n    s->slots[at].live = 0;\n    s->count--;\n    return KV_OK;\n}\nsize_t kv_count(const KVStore *s) {\n    if (!s) return 0;\n    size_t n = 0;\n    for (size_t i = 0; i < KV_CAP; i++) if (s->slots[i].live) n++;\n    return n;\n}\nvoid kv_iter(const KVStore *s, void (*fn)(const char *, long, void *), void *ctx) {\n    if (!s || !fn) return;\n    for (size_t i = 0; i < KV_CAP; i++)\n        if (s->slots[i].live) fn(s->slots[i].key, s->slots[i].value, ctx);\n}\n";
W["cint-p16-kvcore"] = "\nvoid kv_init(KVStore *s) {\n    if (!s) return;\n    memset(s, 0, sizeof *s);\n}\nstatic size_t kv_find(const KVStore *s, const char *key) {\n    for (size_t i = 0; i < KV_CAP; i++)\n        if (s->slots[i].live && strncmp(s->slots[i].key, key, KV_KEYMAX) == 0)\n            return i;\n    return KV_CAP;\n}\nKVError kv_put(KVStore *s, const char *key, long value) {\n    if (!s || !key) return KV_EARGS;\n    if (kv_find(s, key) < KV_CAP) return KV_OK;   /* wrong: replace is a no-op \u2014\n                                                     the old value silently wins */\n    for (size_t i = 0; i < KV_CAP; i++) {\n        if (!s->slots[i].live) {\n            memset(s->slots[i].key, 0, KV_KEYMAX);\n            strncpy(s->slots[i].key, key, KV_KEYMAX - 1);\n            s->slots[i].value = value;\n            s->slots[i].live = 1;\n            s->count++;\n            return KV_OK;\n        }\n    }\n    return KV_ENOMEM;\n}\nKVError kv_get(const KVStore *s, const char *key, long *out) {\n    if (!s || !key || !out) return KV_EARGS;\n    size_t at = kv_find(s, key);\n    if (at == KV_CAP) return KV_ENOENT;\n    *out = s->slots[at].value;\n    return KV_OK;\n}\nKVError kv_del(KVStore *s, const char *key) {\n    if (!s || !key) return KV_EARGS;\n    size_t at = kv_find(s, key);\n    if (at == KV_CAP) return KV_ENOENT;\n    s->slots[at].live = 0;\n    s->count--;\n    return KV_OK;\n}\nsize_t kv_count(const KVStore *s) {\n    if (!s) return 0;\n    size_t n = 0;\n    for (size_t i = 0; i < KV_CAP; i++) if (s->slots[i].live) n++;\n    return n;\n}\nvoid kv_iter(const KVStore *s, void (*fn)(const char *, long, void *), void *ctx) {\n    if (!s || !fn) return;\n    for (size_t i = 0; i < KV_CAP; i++)\n        if (s->slots[i].live) fn(s->slots[i].key, s->slots[i].value, ctx);\n}\n";
