R["cint-p3-arena"] = "\nint arena_init(Arena *a, size_t cap) {\n    if (!a || cap == 0) return 0;\n    a->buf = malloc(cap);\n    if (!a->buf) return 0;\n    a->cap = cap;\n    a->used = 0;\n    return 1;\n}\nvoid *arena_alloc(Arena *a, size_t n) {\n    if (!a || !a->buf || n == 0 || n > a->cap - a->used) return NULL;\n    void *p = a->buf + a->used;\n    a->used += n;\n    memset(p, 0, n);\n    return p;\n}\nvoid arena_destroy(Arena *a) {\n    if (!a) return;\n    free(a->buf);\n    a->buf = NULL;\n    a->cap = a->used = 0;\n}";
W["cint-p3-arena"] = "\nint arena_init(Arena *a, size_t cap) {\n    if (!a || cap == 0) return 0;\n    a->buf = malloc(cap);\n    if (!a->buf) return 0;\n    a->cap = cap;\n    a->used = 0;\n    return 1;\n}\nvoid *arena_alloc(Arena *a, size_t n) {\n    if (!a || !a->buf || n == 0) return NULL;\n    if (a->used + n > a->cap) return NULL;   /* overflow-unsafe add; fine here,\n                                                but this version forgets zeroing */\n    void *p = a->buf + a->used;\n    a->used += n;\n    return p;\n}\nvoid arena_destroy(Arena *a) {\n    if (!a) return;\n    free(a->buf);\n    a->buf = NULL;\n    a->cap = a->used = 0;\n}";
R["cint-checkpoint-m3-task"] = "\nvoid ss_init(StrStack *s) {\n    if (!s) return;\n    s->items = NULL;\n    s->len = 0;\n    s->cap = 0;\n}\nint ss_push(StrStack *s, const char *s2) {\n    if (!s || !s2) return 0;\n    if (s->len == s->cap) {\n        size_t ncap = s->cap ? s->cap * 2 : 8;\n        char **ni = realloc(s->items, ncap * sizeof *ni);\n        if (!ni) return 0;\n        s->items = ni;\n        s->cap = ncap;\n    }\n    size_t n = strlen(s2);\n    char *copy = malloc(n + 1);\n    if (!copy) return 0;\n    memcpy(copy, s2, n + 1);\n    s->items[s->len++] = copy;\n    return 1;\n}\nchar *ss_pop(StrStack *s) {\n    if (!s || s->len == 0) return NULL;\n    return s->items[--s->len];\n}\nconst char *ss_peek(const StrStack *s) {\n    if (!s || s->len == 0) return NULL;\n    return s->items[s->len - 1];\n}\nvoid ss_destroy(StrStack *s) {\n    if (!s) return;\n    for (size_t i = 0; i < s->len; i++) free(s->items[i]);\n    free(s->items);\n    s->items = NULL;\n    s->len = s->cap = 0;\n}";
W["cint-checkpoint-m3-task"] = "\nvoid ss_init(StrStack *s) {\n    if (!s) return;\n    s->items = NULL;\n    s->len = 0;\n    s->cap = 0;\n}\nint ss_push(StrStack *s, const char *s2) {\n    if (!s || !s2) return 0;\n    if (s->len == s->cap) {\n        size_t ncap = s->cap ? s->cap * 2 : 8;\n        char **ni = realloc(s->items, ncap * sizeof *ni);\n        if (!ni) return 0;\n        s->items = ni;\n        s->cap = ncap;\n    }\n    s->items[s->len++] = (char *)s2;   /* wrong: stores borrowed pointer \u2014\n                                          destroy frees caller memory */\n    return 1;\n}\nchar *ss_pop(StrStack *s) {\n    if (!s || s->len == 0) return NULL;\n    return s->items[--s->len];\n}\nconst char *ss_peek(const StrStack *s) {\n    if (!s || s->len == 0) return NULL;\n    return s->items[s->len - 1];\n}\nvoid ss_destroy(StrStack *s) {\n    if (!s) return;\n    for (size_t i = 0; i < s->len; i++) free(s->items[i]);\n    free(s->items);\n    s->items = NULL;\n    s->len = s->cap = 0;\n}";
R["cint-p4-cmp-int"] = "\nint cmp_int(const void *a, const void *b) {\n    int x = *(const int *)a, y = *(const int *)b;\n    return (x > y) - (x < y);\n}\nint cmp_long(const void *a, const void *b) {\n    long x = *(const long *)a, y = *(const long *)b;\n    return (x > y) - (x < y);\n}\nint cmp_str(const void *a, const void *b) {\n    const char *x = *(const char *const *)a, *y = *(const char *const *)b;\n    return strcmp(x, y);\n}";
W["cint-p4-cmp-int"] = "\nint cmp_int(const void *a, const void *b) {\n    return *(const int *)a - *(const int *)b;   /* wrong: overflow on extremes */\n}\nint cmp_long(const void *a, const void *b) {\n    long x = *(const long *)a, y = *(const long *)b;\n    return (x > y) - (x < y);\n}\nint cmp_str(const void *a, const void *b) {\n    const char *x = *(const char *const *)a, *y = *(const char *const *)b;\n    return strcmp(x, y);\n}";
R["cint-p4-desc-stable"] = "\nint cmp_key_asc(const void *a, const void *b) {\n    const Entry *ea = a, *eb = b;\n    return (ea->key > eb->key) - (ea->key < eb->key);\n}\nint cmp_key_desc(const void *a, const void *b) {\n    return -cmp_key_asc(a, b);\n}\nint cmp_name_asc(const void *a, const void *b) {\n    const Entry *ea = a, *eb = b;\n    return strcmp(ea->name, eb->name);\n}";
W["cint-p4-desc-stable"] = "\nint cmp_key_asc(const void *a, const void *b) {\n    const Entry *ea = a, *eb = b;\n    return (ea->key > eb->key) - (ea->key < eb->key);\n}\nint cmp_key_desc(const void *a, const void *b) {\n    const Entry *ea = a, *eb = b;\n    return cmp_key_asc(&ea, &eb);   /* wrong: recursive self-call, not negation */\n}\nint cmp_name_asc(const void *a, const void *b) {\n    const Entry *ea = a, *eb = b;\n    return strcmp(eb->name, ea->name);   /* wrong: descending */\n}";
R["cint-p4-apply-if"] = "\nvoid map_i(int *arr, size_t n, int (*fn)(int)) {\n    if (!arr || !fn) return;\n    for (size_t i = 0; i < n; i++) arr[i] = fn(arr[i]);\n}\nsize_t count_if(const int *arr, size_t n, int (*pred)(int)) {\n    if (!arr || !pred) return 0;\n    size_t c = 0;\n    for (size_t i = 0; i < n; i++) if (pred(arr[i])) c++;\n    return c;\n}\nsize_t filter_i(int *arr, size_t n, int (*pred)(int)) {\n    if (!arr || !pred) return 0;\n    size_t w = 0;\n    for (size_t i = 0; i < n; i++)\n        if (pred(arr[i])) arr[w++] = arr[i];\n    return w;\n}";
W["cint-p4-apply-if"] = "\nvoid map_i(int *arr, size_t n, int (*fn)(int)) {\n    if (!arr || !fn) return;\n    for (size_t i = 0; i < n; i++) arr[i] = fn(arr[i]);\n}\nsize_t count_if(const int *arr, size_t n, int (*pred)(int)) {\n    if (!arr || !pred) return 0;\n    size_t c = 0;\n    for (size_t i = 0; i < n; i++) if (pred(arr[i])) c++;\n    return c;\n}\nsize_t filter_i(int *arr, size_t n, int (*pred)(int)) {\n    if (!arr || !pred) return 0;\n    size_t w = 0;\n    for (size_t i = 0; i < n; i++)\n        if (!pred(arr[i])) arr[w++] = arr[i];   /* wrong: keeps failures */\n    return w;\n}";
R["cint-p4-accumulator"] = "\nint fold_i(const int *arr, size_t n, int init, int (*fn)(int acc, int v)) {\n    if (!fn) return init;\n    int acc = init;\n    if (!arr) return acc;\n    for (size_t i = 0; i < n; i++) acc = fn(acc, arr[i]);\n    return acc;\n}\nint sum_i(const int *arr, size_t n) {\n    return fold_i(arr, n, 0, &fn_add);\n}\nint max_i(const int *arr, size_t n) {\n    return fold_i(arr, n, INT_MIN, &fn_max);\n}";
W["cint-p4-accumulator"] = "\nint fold_i(const int *arr, size_t n, int init, int (*fn)(int acc, int v)) {\n    if (!fn) return init;\n    int acc = init;\n    if (!arr) return acc;\n    for (size_t i = 0; i < n; i++) acc = fn(acc, arr[i]);\n    return acc;\n}\nint sum_i(const int *arr, size_t n) {\n    return fold_i(arr, n, 0, &fn_max);   /* wrong: max instead of add */\n}\nint max_i(const int *arr, size_t n) {\n    return fold_i(arr, n, INT_MIN, &fn_max);\n}";
R["cint-p4-fp-array"] = "\nstatic int op_nop(int a, int b) { (void)b; return a; }\nstatic int op_add(int a, int b) { return a + b; }\nstatic int op_sub(int a, int b) { return a - b; }\nstatic int op_mul(int a, int b) { return a * b; }\nstatic int (*OPS[4])(int, int) = { op_nop, op_add, op_sub, op_mul };\nint run_op(int code, int a, int b) {\n    if (code < 0 || code >= 4) return -1;\n    return OPS[code](a, b);\n}\nint op_valid(int code) {\n    return code >= 0 && code < 4;\n}";
W["cint-p4-fp-array"] = "\nstatic int op_nop(int a, int b) { (void)b; return a; }\nstatic int op_add(int a, int b) { return a + b; }\nstatic int op_sub(int a, int b) { return a - b; }\nstatic int op_mul(int a, int b) { return a * b; }\nstatic int (*OPS[4])(int, int) = { op_nop, op_add, op_sub, op_mul };\nint run_op(int code, int a, int b) {\n    return OPS[code](a, b);   /* wrong: no bounds check */\n}\nint op_valid(int code) {\n    return code >= 0 && code < 4;\n}";
R["cint-p4-context-cb"] = "\nvoid for_each_i(size_t n, void (*visit)(size_t i, void *ctx), void *ctx) {\n    if (!visit) return;\n    for (size_t i = 0; i < n; i++) visit(i, ctx);\n}\nstatic void stats_visitor(size_t i, void *c) {\n    StatsCtx *s = c;\n    s->total += (long long)i;\n    s->count++;\n}\nvoid stats_collect(size_t n, StatsCtx *ctx) {\n    if (!ctx) return;\n    for_each_i(n, stats_visitor, ctx);\n}";
W["cint-p4-context-cb"] = "\nvoid for_each_i(size_t n, void (*visit)(size_t i, void *ctx), void *ctx) {\n    if (!visit) return;\n    for (size_t i = 0; i < n; i++) visit(i, ctx);\n}\nstatic void stats_visitor(size_t i, void *c) {\n    StatsCtx *s = c;\n    s->total += (long long)i;\n}\nvoid stats_collect(size_t n, StatsCtx *ctx) {\n    if (!ctx) return;\n    for_each_i(n, stats_visitor, ctx);\n}";
R["cint-p4-sort-by-flag"] = "\nstatic int cmp_asc(const void *a, const void *b) {\n    int x = *(const int *)a, y = *(const int *)b;\n    return (x > y) - (x < y);\n}\nstatic int cmp_desc(const void *a, const void *b) {\n    return -cmp_asc(a, b);\n}\nint sort_i_mode(int *arr, size_t n, int mode) {\n    if (!arr || (mode != 0 && mode != 1)) return -1;\n    qsort(arr, n, sizeof(int), mode == 0 ? cmp_asc : cmp_desc);\n    return mode;\n}\nint which_mode_sorted(int *arr, size_t n) {\n    if (!arr) return -1;\n    int asc = 1, desc = 1;\n    for (size_t i = 1; i < n; i++) {\n        if (arr[i - 1] > arr[i]) asc = 0;\n        if (arr[i - 1] < arr[i]) desc = 0;\n    }\n    if (asc) return 0;\n    if (desc) return 1;\n    return -1;\n}";
W["cint-p4-sort-by-flag"] = "\nstatic int cmp_asc(const void *a, const void *b) {\n    int x = *(const int *)a, y = *(const int *)b;\n    return (x > y) - (x < y);\n}\nstatic int cmp_desc(const void *a, const void *b) {\n    return -cmp_asc(a, b);\n}\nint sort_i_mode(int *arr, size_t n, int mode) {\n    if (!arr || (mode != 0 && mode != 1)) return -1;\n    qsort(arr, n, sizeof(int), mode == 0 ? cmp_asc : cmp_desc);\n    return mode;\n}\nint which_mode_sorted(int *arr, size_t n) {\n    if (!arr) return -1;\n    sort_i_mode(arr, n, 0);   /* wrong: destroys the caller's array AND\n                                 reports asc for already-ascending input */\n    for (size_t i = 1; i < n; i++)\n        if (arr[i - 1] > arr[i]) return 1;\n    return 0;\n}";
R["cint-checkpoint-m4-task"] = "\nstatic int (*SLOTS[64])(int);\nint bus_register(int id, int (*handler)(int)) {\n    if (id < 0 || id >= 64 || !handler || SLOTS[id]) return 0;\n    SLOTS[id] = handler;\n    return 1;\n}\nint bus_emit(int id, int v) {\n    if (id < 0 || id >= 64 || !SLOTS[id]) return -1;\n    return SLOTS[id](v);\n}\nint bus_unregister(int id) {\n    if (id < 0 || id >= 64 || !SLOTS[id]) return 0;\n    SLOTS[id] = NULL;\n    return 1;\n}\nint bus_broadcast(int v) {\n    int total = 0;\n    for (int i = 0; i < 64; i++)\n        if (SLOTS[i]) total += SLOTS[i](v);\n    return total;\n}";
