R["cint-p3-balanced-paths"] = "\nint format_stats(int n, double d, char **out) {\n    if (!out) return 0;\n    char *first = malloc(64);\n    if (!first) return 0;\n    char *second = malloc(64);\n    if (!second) { free(first); return 0; }    /* the balancing act */\n    int n1 = snprintf(first, 64, \"N=%d;\", n);\n    int n2 = snprintf(second, 64, \"D=%g\", d);\n    if (n1 < 0 || n2 < 0 || (size_t)n1 >= 64 || (size_t)n2 >= 64) {\n        free(first);\n        free(second);\n        return 0;\n    }\n    char *joined = malloc((size_t)n1 + (size_t)n2 + 1);\n    if (!joined) { free(first); free(second); return 0; }\n    memcpy(joined, first, (size_t)n1);\n    memcpy(joined + n1, second, (size_t)n2 + 1);\n    free(first);\n    free(second);\n    *out = joined;\n    return 1;\n}";
W["cint-p3-balanced-paths"] = "\nint format_stats(int n, double d, char **out) {\n    if (!out) return 0;\n    char *first = malloc(64);\n    if (!first) return 0;\n    char *second = malloc(64);\n    if (!second) return 0;   /* wrong: first leaks on this path */\n    int n1 = snprintf(first, 64, \"N=%d \", n);   /* wrong: no semicolon */\n    int n2 = snprintf(second, 64, \"D=%g\", d);\n    if (n1 < 0 || n2 < 0) {\n        free(first);\n        free(second);\n        return 0;\n    }\n    char *joined = malloc((size_t)n1 + (size_t)n2 + 1);\n    if (!joined) { free(first); free(second); return 0; }\n    memcpy(joined, first, (size_t)n1);\n    memcpy(joined + n1, second, (size_t)n2 + 1);\n    free(first);\n    free(second);\n    *out = joined;\n    return 1;\n}";
R["cint-p3-owning-table"] = "\nvoid ot_init(OwnedTable *t) {\n    if (!t) return;\n    t->items = NULL;\n    t->len = 0;\n    t->cap = 0;\n}\nint ot_add(OwnedTable *t, const char *s) {\n    if (!t || !s) return 0;\n    if (t->len == t->cap) {\n        size_t ncap = t->cap ? t->cap * 2 : 8;\n        char **ni = realloc(t->items, ncap * sizeof *ni);\n        if (!ni) return 0;\n        t->items = ni;\n        t->cap = ncap;\n    }\n    size_t n = strlen(s);\n    char *copy = malloc(n + 1);\n    if (!copy) return 0;\n    memcpy(copy, s, n + 1);\n    t->items[t->len++] = copy;\n    return 1;\n}\nsize_t ot_len(const OwnedTable *t) { return t ? t->len : 0; }\nvoid ot_destroy(OwnedTable *t) {\n    if (!t) return;\n    for (size_t i = 0; i < t->len; i++) free(t->items[i]);\n    free(t->items);\n    t->items = NULL;\n    t->len = t->cap = 0;\n}\nint ot_pop(OwnedTable *t) {\n    if (!t || t->len == 0) return 0;\n    free(t->items[--t->len]);\n    return 1;\n}";
W["cint-p3-owning-table"] = "\nvoid ot_init(OwnedTable *t) {\n    if (!t) return;\n    t->items = NULL;\n    t->len = 0;\n    t->cap = 0;\n}\nint ot_add(OwnedTable *t, const char *s) {\n    if (!t || !s) return 0;\n    if (t->len == t->cap) {\n        size_t ncap = t->cap ? t->cap * 2 : 8;\n        char **ni = realloc(t->items, ncap * sizeof *ni);\n        if (!ni) return 0;\n        t->items = ni;\n        t->cap = ncap;\n    }\n    t->items[t->len++] = (char *)s;   /* wrong: stores the borrowed pointer \u2014\n                                         destroy will free caller memory */\n    return 1;\n}\nsize_t ot_len(const OwnedTable *t) { return t ? t->len : 0; }\nvoid ot_destroy(OwnedTable *t) {\n    if (!t) return;\n    for (size_t i = 0; i < t->len; i++) free(t->items[i]);\n    free(t->items);\n    t->items = NULL;\n    t->len = t->cap = 0;\n}\nint ot_pop(OwnedTable *t) {\n    if (!t || t->len == 0) return 0;\n    free(t->items[--t->len]);\n    return 1;\n}";
R["cint-p3-transfer"] = "\nvoid store_copy(char **slot, const char *s) {\n    if (!slot || !s) return;\n    size_t n = strlen(s);\n    char *b = malloc(n + 1);\n    if (!b) return;\n    memcpy(b, s, n + 1);\n    *slot = b;\n}\nvoid take_ownership(char **slot, char *s) {\n    if (!slot || !s) return;\n    *slot = s;\n}\nchar *release(char **slot) {\n    if (!slot) return NULL;\n    char *p = *slot;\n    *slot = NULL;\n    return p;\n}";
W["cint-p3-transfer"] = "\nvoid store_copy(char **slot, const char *s) {\n    if (!slot || !s) return;\n    size_t n = strlen(s);\n    char *b = malloc(n + 1);\n    if (!b) return;\n    memcpy(b, s, n + 1);\n    *slot = b;\n}\nvoid take_ownership(char **slot, char *s) {\n    if (!slot || !s) return;\n    size_t n = strlen(s);\n    char *b = malloc(n + 1);   /* wrong: copies instead of taking \u2014 caller's\n                                  pointer now leaks and slot no longer aliases */\n    if (!b) return;\n    memcpy(b, s, n + 1);\n    *slot = b;\n}\nchar *release(char **slot) {\n    if (!slot) return NULL;\n    char *p = *slot;\n    *slot = NULL;\n    return p;\n}";
